(16, 1, '2026-05-19 23:28:07', '2026-05-19 23:28:07', '<!-- wp:paragraph {"className":"is-style-text-display"} -->\n<p class="is-style-text-display">David Kausek.com</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class="wp-block-separator has-alpha-channel-opacity"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph {"align":"center"} -->\n<p class="has-text-align-center">Welcome to my website. More content to come.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {"layout":{"type":"default"}} -->\n<div class="wp-block-group"><!-- wp:video -->\n<figure class="wp-block-video"><video controls poster="https://davidkausek.com/wp-content/uploads/2026/05/2016_david_kausek_reel.mp4.Still001.png" src="https://www.davidkausek.com/video/2016_david_kausek_reel.mp4"></video></figure>\n<!-- /wp:video --></div>\n<!-- /wp:group -->\n\n<!-- wp:template-part {"slug":"footer","theme":"twentytwentyfive","area":"footer"} /-->', 'Front Page', 'Displays your site''s homepage, whether it is set to display latest posts or a static page. The Front Page template takes precedence over all templates.', 'publish', 'closed', 'closed', '', 'front-page', '', '', '2026-05-20 00:17:17', '2026-05-20 00:17:17', '', 0, 'https://davidkausek.com/2026/05/19/front-page/', 0, 'wp_template', '', 0),
