(245, 1, '2026-05-25 00:24:15', '2026-05-25 00:24:15', '<!-- wp:template-part {"slug":"header","theme":"davidk-theme","area":"header"} /-->\n\n<!-- wp:cover {"url":"https://davidkausek.com/wp-content/uploads/2026/05/IMG_6307-1024x768.jpeg","id":83,"alt":"a view of the sunset","hasParallax":true,"dimRatio":60,"customOverlayColor":"#000000","isUserOverlayColor":true,"minHeight":100,"minHeightUnit":"vh","contentPosition":"center center","sizeSlug":"large","metadata":{"categories":["banner"],"patternName":"core/large-header-with-text-and-a-button","name":"Large header with text and a button"},"align":"full"} -->\n<div class="wp-block-cover alignfull has-parallax" style="min-height:100vh"><div role="img" aria-label="a view of the sunset" class="wp-block-cover__image-background wp-image-83 size-large has-parallax" style="background-position:50% 50%;background-image:url(https://davidkausek.com/wp-content/uploads/2026/05/IMG_6307-1024x768.jpeg)"></div><span aria-hidden="true" class="wp-block-cover__background has-background-dim-60 has-background-dim" style="background-color:#000000"></span><div class="wp-block-cover__inner-container"><!-- wp:heading {"className":"alignwide has-white-color has-text-color","style":{"typography":{"fontSize":"48px","lineHeight":"1.2"}}} -->\n<h2 class="wp-block-heading alignwide has-white-color has-text-color" style="font-size:48px;line-height:1.2"><strong><strong>Welcome to my website</strong></strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:site-tagline /-->\n\n<!-- wp:columns {"align":"wide"} -->\n<div class="wp-block-columns alignwide"><!-- wp:column {"width":"60%"} -->\n<div class="wp-block-column" style="flex-basis:60%"><!-- wp:paragraph {"style":{"color":{"text":"#ffffff"}}} -->\n<p class="has-text-color" style="color:#ffffff"></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class="wp-block-buttons"><!-- wp:button {"className":"is-style-outline","style":{"color":{"text":"#ffffff","background":"#000000"}}} -->\n<div class="wp-block-button is-style-outline"><a class="wp-block-button__link has-text-color has-background wp-element-button" href="#myReel" style="color:#ffffff;background-color:#000000">View my reel</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {"className":"is-style-outline","style":{"color":{"text":"#ffffff","background":"#000000"}}} -->\n<div class="wp-block-button is-style-outline"><a class="wp-block-button__link has-text-color has-background wp-element-button" href="https://davidkausek.com/photography" style="color:#ffffff;background-color:#000000">View photography</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class="wp-block-column"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer -->\n<div style="height:100px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {"anchor":"myReel"} -->\n<div class="wp-block-columns" id="myReel"><!-- wp:column {"layout":{"type":"constrained"},"anchor":"myReel"} -->\n<div class="wp-block-column" id="myReel"><!-- wp:pagelayer/pl-heading {"link":"","pagelayer-id":"pqd1130"} -->\n<h2>View my reel</h2>\n<!-- /wp:pagelayer/pl-heading -->\n\n<!-- wp:video -->\n<figure class="wp-block-video"><video controls poster="https://davidkausek.com/wp-content/uploads/2026/05/2016_david_kausek_reel.mp4.Still001.png" src="https://www.davidkausek.com/video/2016_david_kausek_reel.mp4"></video></figure>\n<!-- /wp:video --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer -->\n<div style="height:100px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {"metadata":{"categories":["text"],"patternName":"image-on-solid-color-with-description","name":"Image on solid color with description"},"align":"full"} -->\n<div class="wp-block-columns alignfull"><!-- wp:column {"width":"50%"} -->\n<div class="wp-block-column" style="flex-basis:50%"><!-- wp:cover {"customOverlayColor":"#f6f6f6","isUserOverlayColor":true,"minHeight":600,"className":"is-light"} -->\n<div class="wp-block-cover is-light" style="min-height:600px"><span aria-hidden="true" class="wp-block-cover__background has-background-dim-100 has-background-dim" style="background-color:#f6f6f6"></span><div class="wp-block-cover__inner-container"><!-- wp:image {"id":45,"sizeSlug":"medium","linkDestination":"none","align":"center"} -->\n<figure class="wp-block-image aligncenter size-medium"><img src="https://davidkausek.com/wp-content/uploads/2026/05/davidk-320x320-1-300x300.jpg" alt="" class="wp-image-45"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"verticalAlignment":"center","style":{"spacing":{"padding":{"top":"1em","right":"1em","bottom":"1em","left":"1em"}}}} -->\n<div class="wp-block-column is-vertically-aligned-center" style="padding-top:1em;padding-right:1em;padding-bottom:1em;padding-left:1em"><!-- wp:columns -->\n<div class="wp-block-columns"><!-- wp:column {"width":"320px"} -->\n<div class="wp-block-column" style="flex-basis:320px"><!-- wp:paragraph {"style":{"typography":{"lineHeight":"1.6","fontStyle":"italic","fontWeight":"800"}},"fontSize":"medium","fontFamily":"urbanist"} -->\n<p class="has-urbanist-font-family has-medium-font-size" style="font-style:italic;font-weight:800;line-height:1.6">List of Skills</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {"style":{"typography":{"lineHeight":1.6}}} -->\n<ul style="line-height:1.6" class="wp-block-list"><!-- wp:list-item {"fontSize":"medium"} -->\n<li class="has-medium-font-size">Videographer / Director of Photography</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"fontSize":"medium"} -->\n<li class="has-medium-font-size">Camera Operator</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"fontSize":"medium"} -->\n<li class="has-medium-font-size">Livestream specialist</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"fontSize":"medium"} -->\n<li class="has-medium-font-size">Video Editor</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"fontSize":"medium"} -->\n<li class="has-medium-font-size">Portrait Photography</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"fontSize":"medium"} -->\n<li class="has-medium-font-size">Event Photograpy</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:template-part {"slug":"footer","theme":"davidk-theme","area":"footer"} /-->', 'Front Page', 'Displays your site''s homepage, whether it is set to display latest posts or a static page. The Front Page template takes precedence over all templates.', 'inherit', 'closed', 'closed', '', '86-revision-v1', '', '', '2026-05-25 00:24:15', '2026-05-25 00:24:15', '', 86, 'https://davidkausek.com/?p=245', 0, 'revision', '', 0),
(247, 1, '2026-05-25 00:27:12', '2026-05-25 00:27:12', '<!-- wp:paragraph -->\n<p>Interested in session photography? See details for packages below. Prints are available upon request.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:pagelayer/pl-image {"id":194,"caption_color":"","overlay":"","pagelayer-id":"1my2128","tmpAtts":{"id-full-url":"https://davidkausek.com/wp-content/uploads/2026/05/20151005202811-221fb275-me.jpg","id-thumbnail-url":"https://davidkausek.com/wp-content/uploads/2026/05/20151005202811-221fb275-me-150x150.jpg","id-medium-url":"https://davidkausek.com/wp-content/uploads/2026/05/20151005202811-221fb275-me-300x200.jpg","id-medium_large-url":"https://davidkausek.com/wp-content/uploads/2026/05/20151005202811-221fb275-me.jpg","id-large-url":"https://davidkausek.com/wp-content/uploads/2026/05/20151005202811-221fb275-me.jpg","id-1536x1536-url":"https://davidkausek.com/wp-content/uploads/2026/05/20151005202811-221fb275-me.jpg","id-2048x2048-url":"https://davidkausek.com/wp-content/uploads/2026/05/20151005202811-221fb275-me.jpg","id-url":"https://davidkausek.com/wp-content/uploads/2026/05/20151005202811-221fb275-me.jpg","id-alt":"20151005202811-221fb275-me","id-link":"https://davidkausek.com/20151005202811-221fb275-me/"}} -->\n<p>Lorem Ipsum has been the industry''s standard dummy text ever since the 1500s.</p>\n<!-- /wp:pagelayer/pl-image -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:pagelayer/pl-heading {"link":"","pagelayer-id":"cfy9833"} -->\n<h3>Headshots</h3>\n<!-- /wp:pagelayer/pl-heading -->\n\n<!-- wp:paragraph -->\n<p>Professional headshots for the following:</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>Corporate photos</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Social Media and LinkedIn Profiles</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Actor headshots</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Can be done on indoors or outdoors. Will travel to location or can setup shoot in&nbsp;studio.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:pagelayer/pl-space {"height":"1em","pagelayer-id":"6yt8467"} /-->\n\n<!-- wp:separator -->\n<hr class="wp-block-separator has-alpha-channel-opacity"/>\n<!-- /wp:separator -->\n\n<!-- wp:pagelayer/pl-heading {"link":"","pagelayer-id":"ncx4146"} -->\n<h3>Weddings and Engagement Photos</h3>\n<!-- /wp:pagelayer/pl-heading -->\n\n<!-- wp:paragraph -->\n<p>For Weddings, will travel to venue. Take photos of ceremony, reception, and portraits of wedding party as well as family members.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph -->\n<p>For Engagement photos, will plan with the couple up to 6 locations in the New York Metro area to take high quality portraits for use in both web and print. Can advise usage for "Save the Dates", "Wedding Announcements", and for "Invitations".</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:pagelayer/pl-space {"height":"1em","pagelayer-id":"oiq9928"} /-->\n\n<!-- wp:separator -->\n<hr class="wp-block-separator has-alpha-channel-opacity"/>\n<!-- /wp:separator -->\n\n<!-- wp:pagelayer/pl-heading {"link":"","pagelayer-id":"55l7285"} -->\n<h3>Event Photography</h3>\n<!-- /wp:pagelayer/pl-heading -->\n\n<!-- wp:paragraph -->\n<p>Over 10 years of experience documenting&nbsp;live events.&nbsp;Whether indoors or outdoors, well lit or low lighting will help you capture your event in the best possible way.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>Exhibitions</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Corporate events</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Social events</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Concerts</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Product Promotion</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:pagelayer/pl-space {"height":"1em","pagelayer-id":"m399630"} /-->\n\n<!-- wp:separator -->\n<hr class="wp-block-separator has-alpha-channel-opacity"/>\n<!-- /wp:separator -->\n\n<!-- wp:pagelayer/pl-heading {"link":"","pagelayer-id":"uob4406"} -->\n<h3>Fine Arts Documentation</h3>\n<!-- /wp:pagelayer/pl-heading -->\n\n<!-- wp:paragraph -->\n<p>Will help you document your work for websites, social media, and digital storage.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>Drawings</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Paintings</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Mixed-media pieces</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Sculptures</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Developed film prints</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>Performance art</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:paragraph -->\n<p>Your work will be documented as&nbsp;high quality digital copies, which you can distribute online, create a portfolio, or keep for your records.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:separator -->\n<hr class="wp-block-separator has-alpha-channel-opacity"/>\n<!-- /wp:separator -->\n\n<!-- wp:paragraph -->\n<p>Use the form below to send a message about the photo package you are interested in.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:shortcode -->\n[formlayer id="1"]\n<!-- /wp:shortcode -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'Photo Packages', '', 'inherit', 'closed', 'closed', '', '224-revision-v1', '', '', '2026-05-25 00:27:12', '2026-05-25 00:27:12', '', 224, 'https://davidkausek.com/?p=247', 0, 'revision', '', 0);
