(326, 1, '2026-05-27 12:10:53', '2026-05-27 16:10:53', '<!-- wp:media-text {"animation":"","duration":"2500","delay":"145","align":"full","mediaPosition":"right","mediaId":324,"mediaLink":"https://davidkausek.com/david-camera-4/","linkDestination":"none","mediaType":"image","mediaWidth":60,"verticalAlignment":"top","metadata":{"categories":["banner"],"patternName":"event","name":"Event"},"style":{"color":{"text":"#fffdc7","background":"#202020"},"elements":{"link":{"color":{"text":"#f97f28"}}}}} -->\n<div class="wp-block-media-text alignfull has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-top has-text-color has-background has-link-color" style="color:#fffdc7;background-color:#202020;grid-template-columns:auto 60%"><div class="wp-block-media-text__content"><!-- wp:group {"style":{"spacing":{"padding":{"top":"2em","right":"2em","bottom":"2em","left":"2em"}},"elements":{"link":{"color":{"text":"#fffdc7"}}}}} -->\n<div class="wp-block-group has-link-color" style="padding-top:2em;padding-right:2em;padding-bottom:2em;padding-left:2em"><!-- wp:heading {"style":{"typography":{"fontWeight":"500","fontSize":"48px","lineHeight":"1.15","fontStyle":"normal","textTransform":"capitalize"}}} -->\n<h2 class="wp-block-heading" style="font-size:48px;font-style:normal;font-weight:500;line-height:1.15;text-transform:capitalize">About David</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph -->\n<p>jjj</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {"style":{"elements":{"link":{"color":{"text":"#fffdc7"}}},"color":{"text":"#fffdc7"}}} -->\n<p class="has-text-color has-link-color" style="color:#fffdc7"><strong><a href="#">RSVP →</a></strong></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div><figure class="wp-block-media-text__media"><img src="https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg" alt="" class="wp-image-324 size-full"/></figure></div>\n<!-- /wp:media-text -->', 'David Kausek.com', '', 'inherit', 'closed', 'closed', '', '43-revision-v1', '', '', '2026-05-27 12:10:53', '2026-05-27 16:10:53', '', 43, 'https://davidkausek.com/?p=326', 0, 'revision', '', 0),
(327, 1, '2026-05-27 12:30:44', '2026-05-27 16:30:44', '<!-- wp:media-text {"animation":"","duration":"2500","delay":"145","align":"full","mediaPosition":"right","mediaId":324,"mediaLink":"https://davidkausek.com/david-camera-4/","linkDestination":"none","mediaType":"image","mediaWidth":60,"mediaSizeSlug":"full","verticalAlignment":"top","imageFill":true,"metadata":{"categories":["banner"],"patternName":"event","name":"Event"},"style":{"color":{"text":"#fffdc7","background":"#202020"},"elements":{"link":{"color":{"text":"#f97f28"}}}}} -->\n<div class="wp-block-media-text alignfull has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-top is-image-fill-element has-text-color has-background has-link-color" style="color:#fffdc7;background-color:#202020;grid-template-columns:auto 60%"><div class="wp-block-media-text__content"><!-- wp:group {"style":{"spacing":{"padding":{"top":"2em","right":"2em","bottom":"2em","left":"2em"}},"elements":{"link":{"color":{"text":"#fffdc7"}}}}} -->\n<div class="wp-block-group has-link-color" style="padding-top:2em;padding-right:2em;padding-bottom:2em;padding-left:2em"><!-- wp:heading {"style":{"typography":{"fontWeight":"500","fontSize":"48px","lineHeight":"1.15","fontStyle":"normal","textTransform":"capitalize"}}} -->\n<h2 class="wp-block-heading" style="font-size:48px;font-style:normal;font-weight:500;line-height:1.15;text-transform:capitalize">About David</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I began my career in 2010, stepping into the world of professional videography and photography with a clear vision: to capture moments that matter and tell stories that resonate. I enjoy working in Manhattan and the tri-state area. I also travel to set up and manage shoots in London, Washington, DC, Puerto Rico and anywhere else the client is based.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":"1.5"}}} -->\n<p style="line-height:1.5"></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div><figure class="wp-block-media-text__media"><img src="https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg" alt="" class="wp-image-324 size-full" style="object-position:50% 50%"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'About', '', 'inherit', 'closed', 'closed', '', '43-revision-v1', '', '', '2026-05-27 12:30:44', '2026-05-27 16:30:44', '', 43, 'https://davidkausek.com/?p=327', 0, 'revision', '', 0);
