(354, 1, '2026-05-27 13:38:20', '2026-05-27 17:38:20', '<!-- wp:template-part {"slug":"header","theme":"davidk-theme","area":"header"} /-->\n\n<!-- wp:cover {"url":"https://davidkausek.com/wp-content/uploads/2026/05/IMG_6307-1024x768.jpeg","id":83,"alt":"a view of the sunset","hasParallax":true,"dimRatio":60,"customOverlayColor":"#000000","isUserOverlayColor":true,"minHeight":100,"minHeightUnit":"vh","contentPosition":"center center","sizeSlug":"large","metadata":{"categories":["banner"],"patternName":"core/large-header-with-text-and-a-button","name":"Large header with text and a button"},"align":"full"} -->\n<div class="wp-block-cover alignfull has-parallax" style="min-height:100vh"><div role="img" aria-label="a view of the sunset" class="wp-block-cover__image-background wp-image-83 size-large has-parallax" style="background-position:50% 50%;background-image:url(https://davidkausek.com/wp-content/uploads/2026/05/IMG_6307-1024x768.jpeg)"></div><span aria-hidden="true" class="wp-block-cover__background has-background-dim-60 has-background-dim" style="background-color:#000000"></span><div class="wp-block-cover__inner-container"><!-- wp:heading {"className":"alignwide has-white-color has-text-color","style":{"typography":{"fontSize":"48px","lineHeight":"1.2","fontStyle":"normal","fontWeight":"500"}}} -->\n<h2 class="wp-block-heading alignwide has-white-color has-text-color" style="font-size:48px;font-style:normal;font-weight:500;line-height:1.2"><strong>David Kausek</strong> | Professional Videographer and Photographer</h2>\n<!-- /wp:heading -->\n\n<!-- wp:site-tagline /-->\n\n<!-- wp:columns {"align":"wide"} -->\n<div class="wp-block-columns alignwide"><!-- wp:column {"width":"60%"} -->\n<div class="wp-block-column" style="flex-basis:60%"><!-- wp:paragraph {"style":{"color":{"text":"#ffffff"}}} -->\n<p class="has-text-color" style="color:#ffffff"></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class="wp-block-buttons"><!-- wp:button {"className":"is-style-outline","style":{"color":{"text":"#ffffff","background":"#000000"}}} -->\n<div class="wp-block-button is-style-outline"><a class="wp-block-button__link has-text-color has-background wp-element-button" href="#myReel" style="color:#ffffff;background-color:#000000">View my reel</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {"className":"is-style-outline","style":{"color":{"text":"#ffffff","background":"#000000"}}} -->\n<div class="wp-block-button is-style-outline"><a class="wp-block-button__link has-text-color has-background wp-element-button" href="https://davidkausek.com/photography" style="color:#ffffff;background-color:#000000">View photography</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class="wp-block-column"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer -->\n<div style="height:100px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {"anchor":"myReel"} -->\n<div class="wp-block-columns" id="myReel"><!-- wp:column {"layout":{"type":"constrained"},"anchor":"myReel"} -->\n<div class="wp-block-column" id="myReel"><!-- wp:pagelayer/pl-heading {"link":"","pagelayer-id":"pqd1130"} -->\n<h2>View my reel</h2>\n<!-- /wp:pagelayer/pl-heading -->\n\n<!-- wp:video -->\n<figure class="wp-block-video"><video controls poster="https://davidkausek.com/wp-content/uploads/2026/05/2016_david_kausek_reel.mp4.Still001.png" src="https://www.davidkausek.com/video/2016_david_kausek_reel.mp4"></video></figure>\n<!-- /wp:video --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer -->\n<div style="height:100px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class="wp-block-columns"><!-- wp:column {"style":{"color":{"background":"#1a1a1a"}}} -->\n<div class="wp-block-column has-background" style="background-color:#1a1a1a"><!-- wp:columns {"metadata":{"categories":["text"],"patternName":"image-on-solid-color-with-description","name":"Image on solid color with description"},"align":"full"} -->\n<div class="wp-block-columns alignfull"><!-- wp:column {"width":"50%"} -->\n<div class="wp-block-column" style="flex-basis:50%"><!-- wp:cover {"customOverlayColor":"#f6f6f6","isUserOverlayColor":true,"minHeight":600,"className":"is-light"} -->\n<div class="wp-block-cover is-light" style="min-height:600px"><span aria-hidden="true" class="wp-block-cover__background has-background-dim-100 has-background-dim" style="background-color:#f6f6f6"></span><div class="wp-block-cover__inner-container"><!-- wp:image {"id":45,"sizeSlug":"medium","linkDestination":"none","align":"center"} -->\n<figure class="wp-block-image aligncenter size-medium"><img src="https://davidkausek.com/wp-content/uploads/2026/05/davidk-320x320-1-300x300.jpg" alt="" class="wp-image-45"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"verticalAlignment":"center","style":{"spacing":{"padding":{"top":"1em","right":"1em","bottom":"1em","left":"1em"}}}} -->\n<div class="wp-block-column is-vertically-aligned-center" style="padding-top:1em;padding-right:1em;padding-bottom:1em;padding-left:1em"><!-- wp:columns -->\n<div class="wp-block-columns"><!-- wp:column {"width":"320px"} -->\n<div class="wp-block-column" style="flex-basis:320px"><!-- wp:paragraph {"style":{"typography":{"lineHeight":"1.6","fontStyle":"italic","fontWeight":"800"}},"fontSize":"medium","fontFamily":"urbanist"} -->\n<p class="has-urbanist-font-family has-medium-font-size" style="font-style:italic;font-weight:800;line-height:1.6">List of Skills</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {"style":{"typography":{"lineHeight":1.6}}} -->\n<ul style="line-height:1.6" class="wp-block-list"><!-- wp:list-item {"fontSize":"medium"} -->\n<li class="has-medium-font-size">Videographer / Director of Photography</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"fontSize":"medium"} -->\n<li class="has-medium-font-size">Camera Operator</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"fontSize":"medium"} -->\n<li class="has-medium-font-size">Livestream specialist</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"fontSize":"medium"} -->\n<li class="has-medium-font-size">Video Editor</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"fontSize":"medium"} -->\n<li class="has-medium-font-size">Portrait Photography</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"fontSize":"medium"} -->\n<li class="has-medium-font-size">Event Photograpy</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {"height":"2em","metadata":{"blockVisibility":{"viewport":{"tablet":false,"mobile":false}}}} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class="wp-block-columns"><!-- wp:column -->\n<div class="wp-block-column"><!-- wp:buttons {"layout":{"type":"flex","justifyContent":"center"}} -->\n<div class="wp-block-buttons"><!-- wp:button -->\n<div class="wp-block-button"><a class="wp-block-button__link wp-element-button" href="https://davidkausek.com/about/">Learn About David</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button -->\n<div class="wp-block-button"><a class="wp-block-button__link wp-element-button" href="https://davidkausek.com/photo-packages/">View Photo Packages</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:template-part {"slug":"footer","theme":"davidk-theme","area":"footer"} /-->', 'Front Page', 'Displays your site''s homepage, whether it is set to display latest posts or a static page. The Front Page template takes precedence over all templates.', 'inherit', 'closed', 'closed', '', '86-revision-v1', '', '', '2026-05-27 13:38:20', '2026-05-27 17:38:20', '', 86, 'https://davidkausek.com/?p=354', 0, 'revision', '', 0);
INSERT INTO `wpk3_posts` VALUES
(355, 1, '2026-05-27 13:39:23', '2026-05-27 17:39:23', '<!-- wp:media-text {"animation":"","duration":"2500","delay":"145","align":"full","mediaPosition":"right","mediaId":324,"mediaLink":"https://davidkausek.com/david-camera-4/","linkDestination":"none","mediaType":"image","mediaWidth":60,"mediaSizeSlug":"full","verticalAlignment":"top","imageFill":true,"metadata":{"categories":["banner"],"patternName":"event","name":"Event"},"style":{"color":{"background":"#202020","text":"#fffdc7"},"elements":{"link":{"color":{"text":"#f97f28"}}}}} -->\n<div class="wp-block-media-text alignfull has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-top is-image-fill-element has-text-color has-background has-link-color" style="color:#fffdc7;background-color:#202020;grid-template-columns:auto 60%"><div class="wp-block-media-text__content"><!-- wp:group {"style":{"spacing":{"padding":{"top":"2em","right":"2em","bottom":"2em","left":"2em"}},"elements":{"link":{"color":{"text":"#fffdc7"}}}}} -->\n<div class="wp-block-group has-link-color" style="padding-top:2em;padding-right:2em;padding-bottom:2em;padding-left:2em"><!-- wp:heading {"style":{"typography":{"fontWeight":"500","fontSize":"48px","lineHeight":"1.15","fontStyle":"normal","textTransform":"capitalize"}}} -->\n<h2 class="wp-block-heading" style="font-size:48px;font-style:normal;font-weight:500;line-height:1.15;text-transform:capitalize"></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I began my career in 2010, stepping into the world of professional videography and photography with a clear vision: to capture moments that matter and tell stories that resonate. I enjoy working in Manhattan and the tri-state area. I also travel to set up and manage shoots in London, Washington, DC, Puerto Rico and anywhere else the client is based.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></div><figure class="wp-block-media-text__media"><img src="https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg" alt="" class="wp-image-324 size-full" style="object-position:50% 50%"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:spacer {"height":"1em"} -->\n<div style="height:1em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading">What I do</h3>\n<!-- /wp:heading -->\n\n<!-- wp:table {"animation":"fadeIn","duration":"2000","metadata":{"blockVisibility":{"viewport":{"mobile":false}}},"align":"full","className":"is-style-regular","style":{"color":{"background":"#202020"},"border":{"color":"#2f2f2f"},"css":".wp-block-table td, .wp-block-table th {\\n    vertical-align: top;\\n}"}} -->\n<figure class="wp-block-table alignfull is-style-regular has-custom-css"><table class="has-background has-border-color has-fixed-layout" style="background-color:#202020;border-color:#2f2f2f"><thead><tr><th>Role</th><th>What It Means</th><th>How I Execute It</th></tr></thead><tbody><tr><td>Live‑Stream Technical Director</td><td>Engineer, produce, and manage virtual and hybrid video broadcasts that keep audiences engaged in real time.</td><td>I build robust, scalable streaming solutions using VLAN, NDI, PTZ, 4‑ME, and broadcast‑grade video networking systems. From signal routing to on‑the‑fly troubleshooting, I ensure a flawless live‑stream experience.</td></tr><tr><td>Director of Photography</td><td>Lead the camera and lighting crews to translate a creative vision into striking visual imagery.</td><td>I collaborate with directors, designers, and clients to devise shot lists, lighting plans, and camera setups. On set, I coordinate the team, make real‑time creative decisions, and keep the production on schedule and on budget.</td></tr><tr><td>Photographer</td><td>Capture still images that complement live video content or stand alone as powerful marketing assets.</td><td>I specialize in live events/concerts, corporate portraits, and interviews, using a keen eye for composition, lighting, and storytelling to produce images that enhance the narrative.</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:pagelayer/pl-row {"overlay_state":"","overlay_type":"image","overlay_img":12,"overlay_img_attachment":"fixed","overlay_bg_size":"cover","overlay_transperancy":0.2,"overlay_type_hover":"","ele_scrolling_effects":"true","ele_transparency":"true","pagelayer-id":"0ea6667","tmpAtts":{"overlay_img-full-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200.jpg","overlay_img-thumbnail-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200-150x150.jpg","overlay_img-medium-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200.jpg","overlay_img-medium_large-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200.jpg","overlay_img-large-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200.jpg","overlay_img-1536x1536-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200.jpg","overlay_img-2048x2048-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200.jpg","overlay_img-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200.jpg","overlay_img-alt":"20160721155158-b63f3f8a-cu_s9999x200","overlay_img-link":"https://davidkausek.com/sample-page/20160721155158-b63f3f8a-cu_s9999x200/"},"metadata":{"blockVisibility":{"viewport":{"desktop":false,"tablet":false}}}} -->\n<!-- wp:pagelayer/pl-col {"col":12,"pagelayer-id":"suc9284"} -->\n<!-- wp:heading {"level":4,"style":{"typography":{"fontSize":"22px","fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading" style="margin-bottom:0;font-size:22px;font-style:normal;font-weight:400">Live‑Stream Technical Director </h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I engineer, produce, and manage virtual and hybrid video broadcasts that keep audiences engaged in real time. <br><br><em>How I Execute It</em><br>I build robust, scalable streaming solutions using VLAN, NDI, PTZ, 4‑ME, and broadcast‑grade video networking systems. From signal routing to on‑the‑fly troubleshooting, I ensure a flawless live‑stream experience.<br></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {"level":4,"style":{"typography":{"fontSize":"22px","fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading" style="margin-bottom:0;font-size:22px;font-style:normal;font-weight:400">Director of Photography (DOP) </h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I lead the camera and lighting crews to translate a creative vision into striking visual imagery.<br><br><em>How I Execute It</em><br>I collaborate with directors, designers, and clients to devise shot lists, lighting plans, and camera setups. On set, I coordinate the team, make real‑time creative decisions, and keep the production on schedule and on budget.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {"level":4,"style":{"typography":{"fontSize":"22px","fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading" style="margin-bottom:0;font-size:22px;font-style:normal;font-weight:400">Photographer</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I capture still images that complement live video content or stand alone as powerful marketing assets. <br><br><em>How I Execute It</em><br>I specialize in live events, corporate portraits, and interviews, using a keen eye for composition, lighting, and storytelling to produce images that enhance the narrative.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:pagelayer/pl-col -->\n<!-- /wp:pagelayer/pl-row -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading">My Approach</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {"style":{"typography":{"lineHeight":1.6},"spacing":{"padding":{"right":"10vw"}}}} -->\n<ul style="padding-right:10vw;line-height:1.6" class="wp-block-list"><!-- wp:list-item -->\n<li><strong>Creative Problem Solver</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>I view every technical challenge as an opportunity to innovate, turning potential obstacles into creative solutions.<br><br></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Team‑First Philosophy</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>Production thrives on collaboration. I work hand‑in‑hand with sound, lighting, post‑production, and creative teams to create a unified workflow that delivers the best possible product for my clients.<br><br></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Global Flexibility</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>While rooted in New York City, I’m comfortable traveling worldwide to set up and manage shoots wherever the client’s vision requires.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:pagelayer/pl-divider {"pagelayer-id":"muc113"} /-->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading">Let''s Connect</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">If you’re looking for a dedicated, technically savvy, and creatively driven professional to bring your video or photography project to life, whether it is a live event, a corporate interview, or a global brand campaign, let’s connect and start a conversation.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:shortcode -->\n[formlayer id="1"]\n<!-- /wp:shortcode -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'About David', '', 'inherit', 'closed', 'closed', '', '43-revision-v1', '', '', '2026-05-27 13:39:23', '2026-05-27 17:39:23', '', 43, 'https://davidkausek.com/?p=355', 0, 'revision', '', 0),
(356, 1, '2026-05-27 13:40:26', '2026-05-27 17:40:26', '<!-- wp:media-text {"animation":"","duration":"2500","delay":"145","align":"full","mediaPosition":"right","mediaId":324,"mediaLink":"https://davidkausek.com/david-camera-4/","linkDestination":"none","mediaType":"image","mediaWidth":60,"mediaSizeSlug":"full","verticalAlignment":"top","imageFill":true,"metadata":{"categories":["banner"],"patternName":"event","name":"Event"},"style":{"color":{"background":"#202020","text":"#fffdc7"},"elements":{"link":{"color":{"text":"#f97f28"}}}}} -->\n<div class="wp-block-media-text alignfull has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-top is-image-fill-element has-text-color has-background has-link-color" style="color:#fffdc7;background-color:#202020;grid-template-columns:auto 60%"><div class="wp-block-media-text__content"><!-- wp:group {"style":{"spacing":{"padding":{"top":"2em","right":"2em","bottom":"2em","left":"2em"}},"elements":{"link":{"color":{"text":"#fffdc7"}}}}} -->\n<div class="wp-block-group has-link-color" style="padding-top:2em;padding-right:2em;padding-bottom:2em;padding-left:2em"><!-- wp:heading {"style":{"typography":{"fontWeight":"500","fontSize":"48px","lineHeight":"1.15","fontStyle":"normal","textTransform":"capitalize"}}} -->\n<h2 class="wp-block-heading" style="font-size:48px;font-style:normal;font-weight:500;line-height:1.15;text-transform:capitalize"></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I began my career in 2010, stepping into the world of professional videography and photography with a clear vision: to capture moments that matter and tell stories that resonate. I enjoy working in Manhattan and the tri-state area. I also travel to set up and manage shoots in London, Washington, DC, Puerto Rico and anywhere else the client is based.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></div><figure class="wp-block-media-text__media"><img src="https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg" alt="" class="wp-image-324 size-full" style="object-position:50% 50%"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:spacer {"height":"1em","metadata":{"blockVisibility":{"viewport":{"desktop":false}}}} -->\n<div style="height:1em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading">What I do</h3>\n<!-- /wp:heading -->\n\n<!-- wp:table {"animation":"fadeIn","duration":"2000","metadata":{"blockVisibility":{"viewport":{"mobile":false}}},"align":"full","className":"is-style-regular","style":{"color":{"background":"#202020"},"border":{"color":"#2f2f2f"},"css":".wp-block-table td, .wp-block-table th {\\n    vertical-align: top;\\n}"}} -->\n<figure class="wp-block-table alignfull is-style-regular has-custom-css"><table class="has-background has-border-color has-fixed-layout" style="background-color:#202020;border-color:#2f2f2f"><thead><tr><th>Role</th><th>What It Means</th><th>How I Execute It</th></tr></thead><tbody><tr><td>Live‑Stream Technical Director</td><td>Engineer, produce, and manage virtual and hybrid video broadcasts that keep audiences engaged in real time.</td><td>I build robust, scalable streaming solutions using VLAN, NDI, PTZ, 4‑ME, and broadcast‑grade video networking systems. From signal routing to on‑the‑fly troubleshooting, I ensure a flawless live‑stream experience.</td></tr><tr><td>Director of Photography</td><td>Lead the camera and lighting crews to translate a creative vision into striking visual imagery.</td><td>I collaborate with directors, designers, and clients to devise shot lists, lighting plans, and camera setups. On set, I coordinate the team, make real‑time creative decisions, and keep the production on schedule and on budget.</td></tr><tr><td>Photographer</td><td>Capture still images that complement live video content or stand alone as powerful marketing assets.</td><td>I specialize in live events/concerts, corporate portraits, and interviews, using a keen eye for composition, lighting, and storytelling to produce images that enhance the narrative.</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:pagelayer/pl-row {"overlay_state":"","overlay_type":"image","overlay_img":12,"overlay_img_attachment":"fixed","overlay_bg_size":"cover","overlay_transperancy":0.2,"overlay_type_hover":"","ele_scrolling_effects":"true","ele_transparency":"true","pagelayer-id":"0ea6667","tmpAtts":{"overlay_img-full-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200.jpg","overlay_img-thumbnail-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200-150x150.jpg","overlay_img-medium-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200.jpg","overlay_img-medium_large-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200.jpg","overlay_img-large-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200.jpg","overlay_img-1536x1536-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200.jpg","overlay_img-2048x2048-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200.jpg","overlay_img-url":"https://davidkausek.com/wp-content/uploads/2026/05/20160721155158-b63f3f8a-cu_s9999x200.jpg","overlay_img-alt":"20160721155158-b63f3f8a-cu_s9999x200","overlay_img-link":"https://davidkausek.com/sample-page/20160721155158-b63f3f8a-cu_s9999x200/"},"metadata":{"blockVisibility":{"viewport":{"desktop":false,"tablet":false}}}} -->\n<!-- wp:pagelayer/pl-col {"col":12,"pagelayer-id":"suc9284"} -->\n<!-- wp:heading {"level":4,"style":{"typography":{"fontSize":"22px","fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading" style="margin-bottom:0;font-size:22px;font-style:normal;font-weight:400">Live‑Stream Technical Director </h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I engineer, produce, and manage virtual and hybrid video broadcasts that keep audiences engaged in real time. <br><br><em>How I Execute It</em><br>I build robust, scalable streaming solutions using VLAN, NDI, PTZ, 4‑ME, and broadcast‑grade video networking systems. From signal routing to on‑the‑fly troubleshooting, I ensure a flawless live‑stream experience.<br></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {"level":4,"style":{"typography":{"fontSize":"22px","fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading" style="margin-bottom:0;font-size:22px;font-style:normal;font-weight:400">Director of Photography (DOP) </h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I lead the camera and lighting crews to translate a creative vision into striking visual imagery.<br><br><em>How I Execute It</em><br>I collaborate with directors, designers, and clients to devise shot lists, lighting plans, and camera setups. On set, I coordinate the team, make real‑time creative decisions, and keep the production on schedule and on budget.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {"level":4,"style":{"typography":{"fontSize":"22px","fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading" style="margin-bottom:0;font-size:22px;font-style:normal;font-weight:400">Photographer</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I capture still images that complement live video content or stand alone as powerful marketing assets. <br><br><em>How I Execute It</em><br>I specialize in live events, corporate portraits, and interviews, using a keen eye for composition, lighting, and storytelling to produce images that enhance the narrative.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:pagelayer/pl-col -->\n<!-- /wp:pagelayer/pl-row -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading">My Approach</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {"style":{"typography":{"lineHeight":1.6},"spacing":{"padding":{"right":"10vw"}}}} -->\n<ul style="padding-right:10vw;line-height:1.6" class="wp-block-list"><!-- wp:list-item -->\n<li><strong>Creative Problem Solver</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>I view every technical challenge as an opportunity to innovate, turning potential obstacles into creative solutions.<br><br></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Team‑First Philosophy</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>Production thrives on collaboration. I work hand‑in‑hand with sound, lighting, post‑production, and creative teams to create a unified workflow that delivers the best possible product for my clients.<br><br></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Global Flexibility</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>While rooted in New York City, I’m comfortable traveling worldwide to set up and manage shoots wherever the client’s vision requires.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:pagelayer/pl-divider {"pagelayer-id":"muc113"} /-->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading">Let''s Connect</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">If you’re looking for a dedicated, technically savvy, and creatively driven professional to bring your video or photography project to life, whether it is a live event, a corporate interview, or a global brand campaign, let’s connect and start a conversation.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:shortcode -->\n[formlayer id="1"]\n<!-- /wp:shortcode -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'About David', '', 'inherit', 'closed', 'closed', '', '43-revision-v1', '', '', '2026-05-27 13:40:26', '2026-05-27 17:40:26', '', 43, 'https://davidkausek.com/?p=356', 0, 'revision', '', 0),
