(400, 1, '2026-05-27 19:20:00', '2026-05-27 23:20:00', '<!-- wp:cover {"url":"https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg","id":324,"hasParallax":true,"dimRatio":10,"customOverlayColor":"#9d9996","isUserOverlayColor":false,"minHeight":100,"minHeightUnit":"vh","contentPosition":"center center","isDark":false,"sizeSlug":"full","metadata":{"blockVisibility":{"viewport":{"mobile":false}}},"align":"full","style":{"spacing":{"margin":{"bottom":"-24px"}}},"layout":{"type":"default"}} -->\n<div class="wp-block-cover alignfull is-light has-parallax" style="margin-bottom:-24px;min-height:100vh"><div class="wp-block-cover__image-background wp-image-324 size-full has-parallax" style="background-position:50% 50%;background-image:url(https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg)"></div><span aria-hidden="true" class="wp-block-cover__background has-background-dim-10 has-background-dim" style="background-color:#9d9996"></span><div class="wp-block-cover__inner-container"><!-- wp:columns {"style":{"spacing":{"padding":{"right":"var:preset|spacing|50"}}}} -->\n<div class="wp-block-columns" style="padding-right:var(--wp--preset--spacing--50)"><!-- wp:column {"width":"45.95%"} -->\n<div class="wp-block-column" style="flex-basis:45.95%"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"width":"54.05%"} -->\n<div class="wp-block-column" style="flex-basis:54.05%"><!-- wp:group {"layout":{"type":"flex","flexWrap":"nowrap","justifyContent":"right"}} -->\n<div class="wp-block-group"><!-- wp:pagelayer/pl-col {"content_pos":"flex-end","col":"7","overlay_type":"color","overlay_gradient":"180,#44d3f6,23,#72e584,45,#2ca4eb,100","overlay_transperancy":0.2,"ele_scrolling_effects":"true","ele_vertical_scroll":"true","ele_transparency":"true","ele_transp_level":5.3,"pagelayer-id":"lih4809"} -->\n<!-- wp:pagelayer/pl-heading {"link":"","font_family":"","font_weight":"0","pagelayer-id":"y6z7970"} -->\n<h2>About David</h2>\n<!-- /wp:pagelayer/pl-heading -->\n\n<!-- wp:paragraph {"style":{"border":{"radius":{"topLeft":"18px","topRight":"18px","bottomLeft":"18px","bottomRight":"18px"}},"spacing":{"margin":{"top":"0","bottom":"0"},"padding":{"top":"var:preset|spacing|50","bottom":"var:preset|spacing|50","left":"var:preset|spacing|60","right":"var:preset|spacing|60"}},"color":{"background":"#202020","text":"#fffdc7"},"elements":{"link":{"color":{"text":"#fffdc7"}}},"typography":{"lineHeight":1.6,"fontSize":"16px","fontStyle":"normal","fontWeight":"300"}},"fontFamily":"system-font"} -->\n<p class="has-text-color has-background has-link-color has-system-font-font-family" style="border-top-left-radius:18px;border-top-right-radius:18px;border-bottom-left-radius:18px;border-bottom-right-radius:18px;color:#fffdc7;background-color:#202020;margin-top:0;margin-bottom:0;padding-top:var(--wp--preset--spacing--50);padding-right:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--50);padding-left:var(--wp--preset--spacing--60);font-size:16px;font-style:normal;font-weight:300;line-height:1.6">I began my career in 2006, stepping into the world of professional videography and photography with a clear vision: to capture moments that matter and tell stories that resonate. I enjoy working in Manhattan and the tri-state area. I also travel to set up and manage shoots in Los Angeles, London, Washington, DC, Puerto Rico and anywhere else the client is based.</p>\n<!-- /wp:paragraph -->\n<!-- /wp:pagelayer/pl-col --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:cover {"url":"https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg","id":324,"hasParallax":true,"dimRatio":10,"customOverlayColor":"#9d9996","isUserOverlayColor":false,"minHeight":100,"minHeightUnit":"vh","contentPosition":"center center","isDark":false,"sizeSlug":"full","metadata":{"blockVisibility":{"viewport":{"mobile":false}}},"align":"full","style":{"color":{"duotone":"var:preset|duotone|blue-orange"}},"layout":{"type":"default"}} -->\n<div class="wp-block-cover alignfull is-light has-parallax" style="min-height:100vh"><div class="wp-block-cover__image-background wp-image-324 size-full has-parallax" style="background-position:50% 50%;background-image:url(https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg)"></div><span aria-hidden="true" class="wp-block-cover__background has-background-dim-10 has-background-dim" style="background-color:#9d9996"></span><div class="wp-block-cover__inner-container"><!-- wp:group {"layout":{"type":"flex","flexWrap":"nowrap","justifyContent":"center"}} -->\n<div class="wp-block-group"><!-- wp:pagelayer/pl-col {"content_pos":"flex-end","col":"3","pagelayer-id":"nig8479"} /-->\n\n<!-- wp:pagelayer/pl-col {"content_pos":"flex-end","col":"8","overlay_type":"color","overlay_gradient":"180,#44d3f6,23,#72e584,45,#2ca4eb,100","overlay_transperancy":0.2,"pagelayer-id":"pad9129"} -->\n<!-- wp:heading {"level":3,"style":{"typography":{"fontStyle":"normal","fontWeight":"800"}}} -->\n<h3 class="wp-block-heading" style="font-style:normal;font-weight:800">What I do</h3>\n<!-- /wp:heading -->\n\n<!-- wp:table {"animation":null,"duration":"2000","metadata":{"blockVisibility":{"viewport":{"mobile":false}}},"align":"full","className":"is-style-regular","style":{"css":".wp-block-table td, .wp-block-table th {n    vertical-align: top;n}","typography":{"fontSize":"17px"},"color":{"background":"#000000b0"},"elements":{"link":{"color":{"text":"var:preset|color|white"}}}},"textColor":"white","fontFamily":"system-font","borderColor":"pale-pink"} -->\n<figure class="wp-block-table alignfull is-style-regular has-custom-css has-system-font-font-family" style="font-size:17px"><table class="has-white-color has-text-color has-background has-link-color has-border-color has-pale-pink-border-color has-fixed-layout" style="background-color:#000000b0"><thead><tr><th>Role</th><th>What It Means</th><th>How I Execute It</th></tr></thead><tbody><tr><td>Livestream Technical Director</td><td>Engineer, produce, and manage virtual and hybrid video broadcasts that keep audiences engaged in real time.</td><td>I build robust, scalable streaming solutions using professional cinema cameras, PTZ systems, VLAN, NDI, 4‑ME TD, and broadcast‑grade video networking systems. From signal routing to on‑the‑fly troubleshooting, I ensure a flawless livestream experience.</td></tr><tr><td>Director of Photography</td><td>Lead the camera and lighting crews to translate a creative vision into striking visual imagery.</td><td>I collaborate with directors, designers, and clients to devise creative lighting plans, talent positions and camera setups. On set, I coordinate the team, make real‑time creative decisions, and keep the production on schedule and on budget.</td></tr><tr><td>Photographer</td><td>Capture still images that complement live video content or stand alone as powerful marketing assets. I also utilize the camera as a creative tool to capture emotion and beauty.</td><td>I specialize in live events/concerts, corporate portraits, and interviews, using a keen eye for composition, lighting, and storytelling to produce images that enhance the narrative.</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n<!-- /wp:pagelayer/pl-col --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:media-text {"animation":"","duration":"2500","delay":"145","align":"full","mediaPosition":"right","mediaId":324,"mediaLink":"https://davidkausek.com/david-camera-4/","linkDestination":"none","mediaType":"image","mediaWidth":60,"mediaSizeSlug":"full","verticalAlignment":"top","imageFill":true,"metadata":{"categories":["banner"],"patternName":"event","name":"Event","blockVisibility":{"viewport":{"desktop":false,"tablet":false}}},"style":{"color":{"background":"#202020","text":"#fffdc7"},"elements":{"link":{"color":{"text":"#f97f28"}}}}} -->\n<div class="wp-block-media-text alignfull has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-top is-image-fill-element has-text-color has-background has-link-color" style="color:#fffdc7;background-color:#202020;grid-template-columns:auto 60%"><div class="wp-block-media-text__content"><!-- wp:group {"style":{"spacing":{"padding":{"top":"1em","right":"1em","bottom":"1em","left":"1em"}},"elements":{"link":{"color":{"text":"#fffdc7"}}}}} -->\n<div class="wp-block-group has-link-color" style="padding-top:1em;padding-right:1em;padding-bottom:1em;padding-left:1em"><!-- wp:heading {"style":{"typography":{"fontWeight":"500","fontSize":"48px","lineHeight":"1.15","fontStyle":"normal","textTransform":"capitalize"}}} -->\n<h2 class="wp-block-heading" style="font-size:48px;font-style:normal;font-weight:500;line-height:1.15;text-transform:capitalize">About David</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I began my career in 2006, stepping into the world of professional videography and photography with a clear vision: to capture moments that matter and tell stories that resonate. I enjoy working in Manhattan and the tri-state area. I also travel to set up and manage shoots in Los Angeles, London, Washington, DC, Puerto Rico and anywhere else the client is based.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></div><figure class="wp-block-media-text__media"><img src="https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg" alt="" class="wp-image-324 size-full" style="object-position:50% 50%"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:pagelayer/pl-row {"overlay_state":"","overlay_type":"image","overlay_img":205,"overlay_img_attachment":"fixed","overlay_bg_size":"cover","overlay_transperancy":0.2,"overlay_type_hover":"","ele_scrolling_effects":"true","ele_transparency":"true","pagelayer-id":"0ea6667","tmpAtts":{"overlay_img-full-url":"https://davidkausek.com/wp-content/uploads/2026/05/concert-09.jpg","overlay_img-thumbnail-url":"https://davidkausek.com/wp-content/uploads/2026/05/concert-09-150x150.jpg","overlay_img-medium-url":"https://davidkausek.com/wp-content/uploads/2026/05/concert-09-199x300.jpg","overlay_img-medium_large-url":"https://davidkausek.com/wp-content/uploads/2026/05/concert-09.jpg","overlay_img-large-url":"https://davidkausek.com/wp-content/uploads/2026/05/concert-09.jpg","overlay_img-1536x1536-url":"https://davidkausek.com/wp-content/uploads/2026/05/concert-09.jpg","overlay_img-2048x2048-url":"https://davidkausek.com/wp-content/uploads/2026/05/concert-09.jpg","overlay_img-url":"https://davidkausek.com/wp-content/uploads/2026/05/concert-09.jpg","overlay_img-alt":"concert-09","overlay_img-link":"https://davidkausek.com/concert-09/"},"metadata":{"blockVisibility":{"viewport":{"desktop":false,"tablet":false}}}} -->\n<!-- wp:pagelayer/pl-col {"col":12,"pagelayer-id":"6794332"} -->\n<!-- wp:group {"style":{"spacing":{"padding":{"right":"var:preset|spacing|60","left":"var:preset|spacing|60"}}},"layout":{"type":"constrained"}} -->\n<div class="wp-block-group" style="padding-right:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--60)"><!-- wp:heading {"style":{"spacing":{"padding":{"top":"var:preset|spacing|50"}}}} -->\n<h2 class="wp-block-heading" style="padding-top:var(--wp--preset--spacing--50)">What I do</h2>\n<!-- /wp:heading -->\n\n<!-- wp:heading {"level":4,"style":{"typography":{"fontSize":"22px","fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading" style="margin-bottom:0;font-size:22px;font-style:normal;font-weight:400">Livestream Technical Director</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I engineer, produce, and manage virtual and hybrid video broadcasts that keep audiences engaged in real time. <br><br><em>How I Execute It</em><br>I build robust, scalable streaming solutions using professional cinema cameras, PTZ systems, VLAN, NDI,  4‑ME TD, and broadcast‑grade video networking systems. From signal routing to on‑the‑fly troubleshooting, I ensure a flawless livestream experience.<br></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {"level":4,"style":{"typography":{"fontSize":"22px","fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading" style="margin-bottom:0;font-size:22px;font-style:normal;font-weight:400">Director of Photography (DOP) </h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I lead the camera and lighting crews to translate a creative vision into striking visual imagery.<br><br><em>How I Execute It</em><br>I collaborate with directors, designers, and clients to devise creative lighting plans, talent positions and camera setups. On set, I coordinate the team, make real‑time creative decisions, and keep the production on schedule and on budget.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:heading {"level":4,"style":{"typography":{"fontSize":"22px","fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading" style="margin-bottom:0;font-size:22px;font-style:normal;font-weight:400">Photographer</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I capture still images that complement live video content or stand alone as powerful marketing assets. I also utilize the camera as a creative tool to capture emotion and beauty.<br><br><em>How I Execute It</em><br>I specialize in live events, corporate portraits, and interviews, using a keen eye for composition, lighting, and storytelling to produce images that enhance the narrative.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n<!-- /wp:pagelayer/pl-col -->\n<!-- /wp:pagelayer/pl-row -->\n\n<!-- wp:group {"layout":{"type":"constrained"}} -->\n<div class="wp-block-group"><!-- wp:heading {"level":3,"style":{"css":"@media (max-width: 768px) {\\n    h3 { font-size: 36px; }\\n}"}} -->\n<h3 class="wp-block-heading has-custom-css">My Approach</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {"style":{"typography":{"lineHeight":1.6},"spacing":{"padding":{"right":"10vw"}}}} -->\n<ul style="padding-right:10vw;line-height:1.6" class="wp-block-list"><!-- wp:list-item -->\n<li><strong>Creative Problem Solver</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>I view every technical challenge as an opportunity to innovate, turning potential obstacles into creative solutions.<br><br></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Team‑First Philosophy</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>Production thrives on collaboration. I work hand‑in‑hand with sound, lighting, post‑production, and creative teams to create a unified workflow that delivers the best possible product for my clients.<br><br></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Global Flexibility</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>While rooted in New York City, I’m comfortable traveling worldwide to set up and manage shoots wherever the client’s vision requires.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:cover {"url":"https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg","id":324,"hasParallax":true,"dimRatio":30,"overlayColor":"white","isUserOverlayColor":true,"minHeight":100,"minHeightUnit":"vh","contentPosition":"center center","isDark":false,"sizeSlug":"full","align":"full","style":{"spacing":{"margin":{"bottom":"-24px"}}},"layout":{"type":"default"}} -->\n<div class="wp-block-cover alignfull is-light has-parallax" style="margin-bottom:-24px;min-height:100vh"><div class="wp-block-cover__image-background wp-image-324 size-full has-parallax" style="background-position:50% 50%;background-image:url(https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg)"></div><span aria-hidden="true" class="wp-block-cover__background has-white-background-color has-background-dim-30 has-background-dim"></span><div class="wp-block-cover__inner-container"><!-- wp:group {"layout":{"type":"constrained","justifyContent":"right"}} -->\n<div class="wp-block-group"><!-- wp:pagelayer/pl-col {"content_pos":"flex-start","col":"7","overlay_type":"color","overlay_gradient":"180,#44d3f6,23,#72e584,45,#2ca4eb,100","overlay_transperancy":0.2,"ele_scrolling_effects":"true","ele_vertical_scroll":"true","ele_transparency":"true","ele_transp_level":5.3,"pagelayer-id":"mo79050"} -->\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading">Let''s Connect</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">If you’re looking for a dedicated, technically savvy, and creatively driven professional to bring your video or photography project to life, whether it is a live event, a corporate interview, or a global brand campaign, let’s connect and start a conversation.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:shortcode -->\n[formlayer id="1"]\n<!-- /wp:shortcode -->\n<!-- /wp:pagelayer/pl-col --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph -->', 'About David WP', '', 'inherit', 'closed', 'closed', '', '372-revision-v1', '', '', '2026-05-27 19:20:00', '2026-05-27 23:20:00', '', 372, 'https://davidkausek.com/?p=400', 0, 'revision', '', 0),
