(524, 1, '2026-05-30 16:51:24', '2026-05-30 20:51:24', '<!-- wp:navigation-submenu {"label":"Photography","type":"page","description":"View photography of David Kausek","id":107,"url":"https://davidkausek.com/photography/","kind":"post-type","metadata":{"bindings":{"url":{"source":"core/post-data","args":{"field":"link"}}}}} -->\n<!-- wp:navigation-link {"label":"Concerts","type":"page","description":"View concert photography by David Kausek","id":118,"url":"https://davidkausek.com/photography/concerts/","kind":"post-type","metadata":{"bindings":{"url":{"source":"core/post-data","args":{"field":"link"}}}}} /-->\n\n<!-- wp:navigation-link {"label":"Nature","type":"page","description":"View nature photography by David Kausek","id":122,"url":"https://davidkausek.com/photography/nature/","kind":"post-type","metadata":{"bindings":{"url":{"source":"core/post-data","args":{"field":"link"}}}}} /-->\n\n<!-- wp:navigation-link {"label":"Portraits","type":"page","description":"View portrait photos taken by David Kausek","id":120,"url":"https://davidkausek.com/photography/portraits/","kind":"post-type","metadata":{"bindings":{"url":{"source":"core/post-data","args":{"field":"link"}}}}} /-->\n<!-- /wp:navigation-submenu -->\n\n<!-- wp:navigation-link {"label":"Photo Packages","type":"page","description":"View Photo Packages of Contact David Kausek, a NYC based videographer and photographer","id":224,"url":"https://davidkausek.com/photo-packages/","kind":"post-type","metadata":{"bindings":{"url":{"source":"core/post-data","args":{"field":"link"}}}}} /-->\n\n<!-- wp:navigation-link {"label":"About David","type":"page","description":"Learn more about David Kausek","id":372,"url":"https://davidkausek.com/about/","kind":"post-type","metadata":{"bindings":{"url":{"source":"core/post-data","args":{"field":"link"}}}}} /-->\n\n<!-- wp:navigation-link {"label":"Contact Me","type":"page","description":"Contact David Kausek, a NYC based videographer and photographer","id":60,"url":"https://davidkausek.com/contact-me/","kind":"post-type","metadata":{"bindings":{"url":{"source":"core/post-data","args":{"field":"link"}}}}} /-->', 'Navigation', '', 'inherit', 'closed', 'closed', '', '4-revision-v1', '', '', '2026-05-30 16:51:24', '2026-05-30 20:51:24', '', 4, 'https://davidkausek.com/?p=524', 0, 'revision', '', 0),
