(571, 1, '2026-05-31 13:07:13', '2026-05-31 17:07:13', '{"title":"Connect with David Form","fields":[{"id":"f1780246225050","type":"text","label":"Name","required":true,"options":["Option 1","Option 2","Option 3"],"placeholder":"What is your name?"},{"id":"f1780246272633","type":"email","label":"Email","required":true,"options":["Option 1","Option 2","Option 3"],"placeholder":"Enter your email address"},{"id":"f1780246280983","type":"radio","label":"Which service are you interested in?","required":true,"options":[{"label":"Livestream","value":"services-livestream","default":false},{"label":"Director of Photography (DP)","value":"services-DP","default":false},{"label":"Camera Operator","value":"sevices-camera-operator","default":false},{"label":"Photography - Booking a Session","value":"services-photo-session","default":false},{"label":"Photography - Live Events","value":"services-photo-event","default":false}],"help_text":"Choose an option to start our conversation.","default_value":""},{"id":"f1780246651748","type":"section","label":"Additional Information","required":false,"options":["Option 1","Option 2","Option 3"]},{"id":"f1780246815180","type":"dropdown","label":"When do you need this service?","required":false,"options":[{"label":"Within a week","value":"timeframe-1wk","default":false},{"label":"Within 2 to 4 weeks","value":"timeframe-2to4wks","default":false},{"label":"Within 1 to 2 months","value":"timeframe-1to2mos","default":false},{"label":"Within 3 to 6 months","value":"timeframe-3to6mos","default":false},{"label":"Flexible","value":"timeframe-flex","default":false}],"default_value":"","style_label_color":"#000000"},{"id":"f1780246712780","type":"textarea","label":"Tell me how can I help?","required":false,"options":["Option 1","Option 2","Option 3"]},{"id":"f1780246991745","type":"submit","label":"Send Message","required":false,"options":["Option 1","Option 2","Option 3"]}],"settings":{"notifications":{"enabled":true,"to_email":"{admin_email}","reply_to":"","from_name":"FormLayer","from_email":"{admin_email}","bcc":"","subject":"New Form Submission","message":"You have a new submission: n {all_fields}"},"confirmations":{"type":"message","message":"Thank you! Your submission has been sent successfully.","redirect_url":"","hide_form":true},"integrations":{"slack":{"enabled":false},"mailchimp":{"enabled":false},"sheets":{"enabled":false},"notion":{"enabled":false},"trello":{"enabled":false},"discord":{"enabled":false}},"custom_css":".formlayer-help-text { color: #1a1a1a; }"}}', 'Connect with David Form', '', 'publish', 'closed', 'closed', '', 'untitled-form', '', '', '2026-05-31 13:22:19', '2026-05-31 17:22:19', '', 0, 'https://davidkausek.com/?p=571', 0, 'formlayer_form', '', 0),
(572, 1, '2026-05-31 13:08:11', '2026-05-31 17:08:11', '<!-- wp:media-text {"align":"full","mediaPosition":"right","mediaId":324,"mediaLink":"https://davidkausek.com/david-camera-4/","linkDestination":"none","mediaType":"image","mediaWidth":60,"mediaSizeSlug":"full","verticalAlignment":"top","imageFill":true,"metadata":{"categories":["banner"],"patternName":"event","name":"Event"},"className":"animated fadeIn slow","style":{"color":{"background":"#202020","text":"#fffdc7"},"elements":{"link":{"color":{"text":"#f97f28"}}}}} -->\n<div class="wp-block-media-text alignfull has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-top is-image-fill-element animated fadeIn slow has-text-color has-background has-link-color" style="color:#fffdc7;background-color:#202020;grid-template-columns:auto 60%"><div class="wp-block-media-text__content"><!-- wp:group {"style":{"spacing":{"padding":{"top":"1em","right":"1em","bottom":"1em","left":"1em"}},"elements":{"link":{"color":{"text":"#fffdc7"}}}},"layout":{"type":"default"}} -->\n<div class="wp-block-group has-link-color" style="padding-top:1em;padding-right:1em;padding-bottom:1em;padding-left:1em"><!-- wp:heading {"style":{"typography":{"fontWeight":"500","fontSize":"48px","lineHeight":"1.15","fontStyle":"normal","textTransform":"capitalize"}}} -->\n<h2 class="wp-block-heading" style="font-size:48px;font-style:normal;font-weight:500;line-height:1.15;text-transform:capitalize"></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6,"fontSize":"1.25em"}}} -->\n<p style="font-size:1.25em;line-height:1.6">I began my career in 2006, stepping into the world of professional videography and photography with a clear vision: to capture moments that matter and tell stories that resonate. I enjoy working in Manhattan and the tri-state area. I also travel to set up and manage shoots in Los Angeles, London, Washington, DC, Puerto Rico and anywhere else the client is based.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></div><figure class="wp-block-media-text__media"><img src="https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg" alt="" class="wp-image-324 size-full" style="object-position:50% 50%"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:spacer {"height":"1em","metadata":{"blockVisibility":{"viewport":{"desktop":false}}}} -->\n<div style="height:1em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class="wp-block-columns"><!-- wp:column -->\n<div class="wp-block-column"><!-- wp:heading {"level":3,"className":"animated fadeIn slow"} -->\n<h3 class="wp-block-heading animated fadeIn slow">What I do</h3>\n<!-- /wp:heading -->\n\n<!-- wp:table {"metadata":{"blockVisibility":{"viewport":{"mobile":false}}},"align":"full","className":"is-style-regular animated fadeIn slow","style":{"color":{"background":"#202020"},"border":{"color":"#2f2f2f"},"css":".wp-block-table td, .wp-block-table th {\\n    vertical-align: top;\\n}","typography":{"fontSize":"1.2em"}}} -->\n<figure class="wp-block-table alignfull is-style-regular animated fadeIn slow has-custom-css" style="font-size:1.2em"><table class="has-background has-border-color has-fixed-layout" style="background-color:#202020;border-color:#2f2f2f"><thead><tr><th>Role</th><th>What It Means</th><th>How I Execute It</th></tr></thead><tbody><tr><td>Livestream Technical Director</td><td>Engineer, produce, and manage virtual and hybrid video broadcasts that keep audiences engaged in real time.</td><td>I build robust, scalable streaming solutions using professional cinema cameras, PTZ systems, VLAN, NDI, 4‑ME TD, and broadcast‑grade video networking systems. From signal routing to on‑the‑fly troubleshooting, I ensure a flawless livestream experience.</td></tr><tr><td>Director of Photography</td><td>Lead the camera and lighting crews to translate a creative vision into striking visual imagery.</td><td>I collaborate with directors, designers, and clients to devise creative lighting plans, talent positions and camera setups. On set, I coordinate the team, make real‑time creative decisions, and keep the production on schedule and on budget.</td></tr><tr><td>Photographer</td><td>Capture still images that complement live video content or stand alone as powerful marketing assets. I also utilize the camera as a creative tool to capture emotion and beauty.</td><td>I specialize in live events/concerts, corporate portraits, and interviews, using a keen eye for composition, lighting, and storytelling to produce images that enhance the narrative.</td></tr></tbody></table></figure>\n<!-- /wp:table --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {"metadata":{"blockVisibility":{"viewport":{"desktop":false,"tablet":false}}},"style":{"color":{"gradient":"linear-gradient(180deg,rgba(255,206,166,0.16) 0%,rgba(255,46,46,0.28) 51%,rgba(0,0,0,0.22) 100%)"}}} -->\n<div class="wp-block-columns has-background" style="background:linear-gradient(180deg,rgba(255,206,166,0.16) 0%,rgba(255,46,46,0.28) 51%,rgba(0,0,0,0.22) 100%)"><!-- wp:column {"className":"animated fadeIn slow"} -->\n<div class="wp-block-column animated fadeIn slow"><!-- wp:heading {"level":4,"style":{"typography":{"fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading" style="margin-bottom:0;font-style:normal;font-weight:400">Livestream Technical Director</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6,"fontSize":"1.2em"}}} -->\n<p style="font-size:1.2em;line-height:1.6">I engineer, produce, and manage virtual and hybrid video broadcasts that keep audiences engaged in real time. <br><br><em>How I Execute It</em><br>I build robust, scalable streaming solutions using professional cinema cameras, PTZ systems, VLAN, NDI,  4‑ME TD, and broadcast‑grade video networking systems. From signal routing to on‑the‑fly troubleshooting, I ensure a flawless livestream experience.<br></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"className":"animated fadeIn slow"} -->\n<div class="wp-block-column animated fadeIn slow"><!-- wp:heading {"level":4,"style":{"typography":{"fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading" style="margin-bottom:0;font-style:normal;font-weight:400">Director of Photography (DOP) </h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6,"fontSize":"1.2em"}}} -->\n<p style="font-size:1.2em;line-height:1.6">I lead the camera and lighting crews to translate a creative vision into striking visual imagery.<br><br><em>How I Execute It</em><br>I collaborate with directors, designers, and clients to devise creative lighting plans, talent positions and camera setups. On set, I coordinate the team, make real‑time creative decisions, and keep the production on schedule and on budget.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"className":"animated fadeIn slow"} -->\n<div class="wp-block-column animated fadeIn slow"><!-- wp:heading {"level":4,"style":{"typography":{"fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading" style="margin-bottom:0;font-style:normal;font-weight:400">Photographer</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6,"fontSize":"1.2em"}}} -->\n<p style="font-size:1.2em;line-height:1.6">I capture still images that complement live video content or stand alone as powerful marketing assets. I also utilize the camera as a creative tool to capture emotion and beauty.<br><br><em>How I Execute It</em><br>I specialize in live events, corporate portraits, and interviews, using a keen eye for composition, lighting, and storytelling to produce images that enhance the narrative.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {"className":"animated fadeIn slow"} -->\n<div class="wp-block-columns animated fadeIn slow"><!-- wp:column -->\n<div class="wp-block-column"><!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading">My Approach</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {"style":{"typography":{"lineHeight":1.6,"fontSize":"1.2em"},"spacing":{"padding":{"right":"10vw"}}}} -->\n<ul style="padding-right:10vw;font-size:1.2em;line-height:1.6" class="wp-block-list"><!-- wp:list-item {"style":{"typography":{"fontSize":"1em"}}} -->\n<li style="font-size:1em"><strong>Creative Problem Solver</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item {"style":{"typography":{"fontSize":"0.9em"}}} -->\n<li style="font-size:0.9em">I view every technical challenge as an opportunity to innovate, turning potential obstacles into creative solutions.<br><br></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Team‑First Philosophy</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item {"style":{"typography":{"fontSize":"0.9em"}}} -->\n<li style="font-size:0.9em">Production thrives on collaboration. I work hand‑in‑hand with sound, lighting, post‑production, and creative teams to create a unified workflow that delivers the best possible product for my clients.<br><br></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Global Flexibility</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item {"style":{"typography":{"fontSize":"0.9em"}}} -->\n<li style="font-size:0.9em">While rooted in New York City, I’m comfortable traveling worldwide to set up and manage shoots wherever the client’s vision requires.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {"className":"animated fadeIn slow"} -->\n<div class="wp-block-columns animated fadeIn slow"><!-- wp:column -->\n<div class="wp-block-column"><!-- wp:pagelayer/pl-divider {"pagelayer-id":"muc113"} /-->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading">Let''s Connect</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6,"fontSize":"1.2em"}}} -->\n<p style="font-size:1.2em;line-height:1.6">If you’re looking for a dedicated, technically savvy, and creatively driven professional to bring your video or photography project to life, whether it is a live event, a corporate interview, or a global brand campaign, let’s connect and start a conversation.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:shortcode -->\n[formlayer id="1"]\n<!-- /wp:shortcode --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'About David Old', '', 'inherit', 'closed', 'closed', '', '43-revision-v1', '', '', '2026-05-31 13:08:11', '2026-05-31 17:08:11', '', 43, 'https://davidkausek.com/?p=572', 0, 'revision', '', 0);
INSERT INTO `wpk3_posts` VALUES
(573, 1, '2026-05-31 13:08:28', '2026-05-31 17:08:28', '<!-- wp:cover {"url":"https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg","id":324,"hasParallax":true,"dimRatio":10,"customOverlayColor":"#9d9996","isUserOverlayColor":false,"minHeight":100,"minHeightUnit":"vh","contentPosition":"center center","isDark":false,"sizeSlug":"full","metadata":{"blockVisibility":{"viewport":{"mobile":false}}},"align":"full","style":{"spacing":{"margin":{"bottom":"-24px"}}},"layout":{"type":"default"}} -->\n<div class="wp-block-cover alignfull is-light has-parallax" style="margin-bottom:-24px;min-height:100vh"><div class="wp-block-cover__image-background wp-image-324 size-full has-parallax" style="background-position:50% 50%;background-image:url(https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg)"></div><span aria-hidden="true" class="wp-block-cover__background has-background-dim-10 has-background-dim" style="background-color:#9d9996"></span><div class="wp-block-cover__inner-container"><!-- wp:columns {"style":{"spacing":{"padding":{"right":"var:preset|spacing|80"}}}} -->\n<div class="wp-block-columns" style="padding-right:var(--wp--preset--spacing--80)"><!-- wp:column {"width":"45.95%"} -->\n<div class="wp-block-column" style="flex-basis:45.95%"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"width":"50%"} -->\n<div class="wp-block-column" style="flex-basis:50%"><!-- wp:group {"layout":{"type":"flex","flexWrap":"nowrap","justifyContent":"right","verticalAlignment":"top"}} -->\n<div class="wp-block-group"><!-- wp:pagelayer/pl-col {"content_pos":"flex-end","col":"7","overlay_type":"color","overlay_gradient":"180,#44d3f6,23,#72e584,45,#2ca4eb,100","overlay_transperancy":0.2,"ele_scrolling_effects":"true","ele_vertical_scroll":"true","ele_transparency":"true","ele_transp_level":5.3,"pagelayer-id":"lih4809"} -->\n<!-- wp:pagelayer/pl-heading {"link":"","heading_typo":{"font-size":"48","font-weight":"normal"},"heading_typo_tablet":[],"heading_typo_mobile":[],"font_family":"","font_weight":"bold","pagelayer-id":"y6z7970"} -->\n<h2>About David</h2>\n<!-- /wp:pagelayer/pl-heading -->\n\n<!-- wp:heading {"className":"animated fadeIn","style":{"typography":{"fontSize":"2em"},"color":{"background":"#ffffff82"},"border":{"radius":{"topLeft":"8px","topRight":"8px","bottomLeft":"8px","bottomRight":"8px"}},"spacing":{"padding":{"right":"1.5em","left":"1.5em"}}}} -->\n<h2 class="wp-block-heading animated fadeIn has-background" style="border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px;background-color:#ffffff82;padding-right:1.5em;padding-left:1.5em;font-size:2em">I began my career in 2006, stepping into the world of professional videography and photography with a clear vision: to capture moments that matter and tell stories that resonate. I enjoy working in Manhattan and the tri-state area. I also travel to set up and manage shoots in Los Angeles, London, Washington, DC, Puerto Rico and anywhere else the client is based.</h2>\n<!-- /wp:heading -->\n<!-- /wp:pagelayer/pl-col --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:media-text {"align":"full","mediaPosition":"right","mediaId":324,"mediaLink":"https://davidkausek.com/david-camera-4/","linkDestination":"none","mediaType":"image","mediaWidth":60,"mediaSizeSlug":"full","verticalAlignment":"top","imageFill":true,"metadata":{"categories":["banner"],"patternName":"event","name":"Event","blockVisibility":{"viewport":{"desktop":false,"tablet":false}}},"style":{"elements":{"link":{"color":{"text":"#f97f28"}}},"spacing":{"margin":{"top":"0","bottom":"0","left":"0em","right":"0em"}}},"backgroundColor":"custom-dark-gray","textColor":"custom-light-yellow"} -->\n<div class="wp-block-media-text alignfull has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-top is-image-fill-element has-custom-light-yellow-color has-custom-dark-gray-background-color has-text-color has-background has-link-color" style="margin-top:0;margin-right:0em;margin-bottom:0;margin-left:0em;grid-template-columns:auto 60%"><div class="wp-block-media-text__content"><!-- wp:group {"style":{"spacing":{"padding":{"top":"1em","right":"0em","bottom":"1em","left":"0em"}}}} -->\n<div class="wp-block-group" style="padding-top:1em;padding-right:0em;padding-bottom:1em;padding-left:0em"><!-- wp:heading {"className":"animated fadeIn slow","style":{"typography":{"fontWeight":"500","lineHeight":"1.15","fontStyle":"normal","textTransform":"capitalize"},"elements":{"link":{"color":{"text":"var:preset|color|white"}}}},"textColor":"white"} -->\n<h2 class="wp-block-heading animated fadeIn slow has-white-color has-text-color has-link-color" style="font-style:normal;font-weight:500;line-height:1.15;text-transform:capitalize">About David</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slower","style":{"typography":{"lineHeight":1.6,"fontStyle":"normal","fontWeight":"500","fontSize":"1.5em"}},"fontFamily":"urbanist"} -->\n<p class="animated fadeIn slower has-urbanist-font-family" style="font-size:1.5em;font-style:normal;font-weight:500;line-height:1.6">I began my career in 2006, stepping into the world of professional videography and photography with a clear vision: to capture moments that matter and tell stories that resonate. I enjoy working in Manhattan and the tri-state area. I also travel to set up and manage shoots in Los Angeles, London, Washington, DC, Puerto Rico and anywhere else the client is based.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group -->\n\n<!-- wp:paragraph -->\n<p></p>\n<!-- /wp:paragraph --></div><figure class="wp-block-media-text__media"><img src="https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg" alt="" class="wp-image-324 size-full" style="object-position:50% 50%"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:columns {"backgroundColor":"custom-darker-gray"} -->\n<div class="wp-block-columns has-custom-darker-gray-background-color has-background"><!-- wp:column {"width":"100%"} -->\n<div class="wp-block-column" style="flex-basis:100%"><!-- wp:heading {"level":3,"className":"animated fadeIn","style":{"spacing":{"padding":{"top":"var:preset|spacing|50"}},"typography":{"fontStyle":"normal","fontWeight":"500"}}} -->\n<h3 class="wp-block-heading animated fadeIn" style="padding-top:var(--wp--preset--spacing--50);font-style:normal;font-weight:500">What I do</h3>\n<!-- /wp:heading -->\n\n<!-- wp:columns -->\n<div class="wp-block-columns"><!-- wp:column {"verticalAlignment":"stretch","width":"100%","className":"animated fadeIn","style":{"color":{"background":"#fffdc729"},"border":{"radius":{"topLeft":"8px","topRight":"8px","bottomLeft":"8px","bottomRight":"8px"}}}} -->\n<div class="wp-block-column is-vertically-aligned-stretch animated fadeIn has-background" style="border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px;background-color:#fffdc729;flex-basis:100%"><!-- wp:group {"style":{"spacing":{"padding":{"right":"var:preset|spacing|60","left":"var:preset|spacing|60","top":"1.5em","bottom":"1.5em"}},"typography":{"fontSize":"18px"}},"layout":{"type":"default"}} -->\n<div class="wp-block-group" style="padding-top:1.5em;padding-right:var(--wp--preset--spacing--60);padding-bottom:1.5em;padding-left:var(--wp--preset--spacing--60);font-size:18px"><!-- wp:heading {"level":4,"style":{"typography":{"fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading" style="margin-bottom:0;font-style:normal;font-weight:400">Livestream Technical Director</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I engineer, produce, and manage virtual and hybrid video broadcasts that keep audiences engaged in real time. <br><br><em>How I Execute It</em><br>I build robust, scalable streaming solutions using professional cinema cameras, PTZ systems, VLAN, NDI,  4‑ME TD, and broadcast‑grade video networking systems. From signal routing to on‑the‑fly troubleshooting, I ensure a flawless livestream experience.<br></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"verticalAlignment":"stretch","width":"100%","className":"animated fadeIn","style":{"color":{"background":"#fffdc729"},"border":{"radius":{"topLeft":"8px","topRight":"8px","bottomLeft":"8px","bottomRight":"8px"}}}} -->\n<div class="wp-block-column is-vertically-aligned-stretch animated fadeIn has-background" style="border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px;background-color:#fffdc729;flex-basis:100%"><!-- wp:group {"style":{"spacing":{"padding":{"right":"var:preset|spacing|60","left":"var:preset|spacing|60","top":"1.5em","bottom":"1.5em"}},"typography":{"fontSize":"18px"}},"layout":{"type":"default"}} -->\n<div class="wp-block-group" style="padding-top:1.5em;padding-right:var(--wp--preset--spacing--60);padding-bottom:1.5em;padding-left:var(--wp--preset--spacing--60);font-size:18px"><!-- wp:heading {"level":4,"style":{"typography":{"fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading" style="margin-bottom:0;font-style:normal;font-weight:400">Director of Photography (DP)</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I lead the camera and lighting crews to translate a creative vision into striking visual imagery.<br><br><em>How I Execute It</em><br>I collaborate with directors, designers, and clients to devise creative lighting plans, talent positions and camera setups. On set, I coordinate the team, make real‑time creative decisions, and keep the production on schedule and on budget.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"verticalAlignment":"stretch","width":"100%","className":"animated fadeIn","style":{"color":{"background":"#fffdc729"},"border":{"radius":{"topLeft":"8px","topRight":"8px","bottomLeft":"8px","bottomRight":"8px"}}}} -->\n<div class="wp-block-column is-vertically-aligned-stretch animated fadeIn has-background" style="border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px;background-color:#fffdc729;flex-basis:100%"><!-- wp:group {"style":{"spacing":{"padding":{"right":"var:preset|spacing|60","left":"var:preset|spacing|60","top":"1.5em","bottom":"1.5em"}},"typography":{"fontSize":"18px"}},"layout":{"type":"default"}} -->\n<div class="wp-block-group" style="padding-top:1.5em;padding-right:var(--wp--preset--spacing--60);padding-bottom:1.5em;padding-left:var(--wp--preset--spacing--60);font-size:18px"><!-- wp:heading {"level":4,"style":{"typography":{"fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading" style="margin-bottom:0;font-style:normal;font-weight:400">Photographer</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"lineHeight":1.6}}} -->\n<p style="line-height:1.6">I capture still images that complement live video content or stand alone as powerful marketing assets. I also utilize the camera as a creative tool to capture emotion and beauty.<br><br><em>How I Execute It</em><br>I specialize in live events, corporate portraits, and interviews, using a keen eye for composition, lighting, and storytelling to produce images that enhance the narrative.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {"height":"32px","width":"0px","style":{"layout":[]}} -->\n<div style="height:32px;width:0px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:group {"style":{"spacing":{"padding":{"right":"var:preset|spacing|60","left":"var:preset|spacing|60","top":"var:preset|spacing|60","bottom":"var:preset|spacing|60"}}},"layout":{"type":"constrained"}} -->\n<div class="wp-block-group" style="padding-top:var(--wp--preset--spacing--60);padding-right:var(--wp--preset--spacing--60);padding-bottom:var(--wp--preset--spacing--60);padding-left:var(--wp--preset--spacing--60)"><!-- wp:heading {"level":3,"className":"animated fadeIn","style":{"css":"@media (max-width: 768px) {\\n    h3 { font-size: 36px; }\\n}","typography":{"fontStyle":"normal","fontWeight":"400"}}} -->\n<h3 class="wp-block-heading animated fadeIn has-custom-css" style="font-style:normal;font-weight:400">My Approach</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {"style":{"typography":{"lineHeight":1.6,"fontSize":"20px"},"spacing":{"padding":{"right":"0vw","top":"0"}}}} -->\n<ul style="padding-top:0;padding-right:0vw;font-size:20px;line-height:1.6" class="wp-block-list"><!-- wp:list-item {"className":"animated fadeIn"} -->\n<li class="animated fadeIn"><strong>Creative Problem Solver</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>I view every technical challenge as an opportunity to innovate, turning potential obstacles into creative solutions.<br><br></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"className":"animated fadeIn"} -->\n<li class="animated fadeIn"><strong>Team‑First Philosophy</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>Production thrives on collaboration. I work hand‑in‑hand with sound, lighting, post‑production, and creative teams to create a unified workflow that delivers the best possible product for my clients.<br><br></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"className":"animated fadeIn"} -->\n<li class="animated fadeIn"><strong>Global Flexibility</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>While rooted in New York City, I’m comfortable traveling worldwide to set up and manage shoots wherever the client’s vision requires.</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {"height":"32px","width":"0px","style":{"layout":[]}} -->\n<div style="height:32px;width:0px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:cover {"url":"https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg","id":324,"hasParallax":true,"dimRatio":50,"overlayColor":"white","isUserOverlayColor":true,"focalPoint":{"x":0.85,"y":0.62},"minHeight":100,"minHeightUnit":"vh","contentPosition":"center center","isDark":false,"sizeSlug":"full","align":"full","style":{"spacing":{"margin":{"bottom":"-24px"}}},"layout":{"type":"default"}} -->\n<div class="wp-block-cover alignfull is-light has-parallax" style="margin-bottom:-24px;min-height:100vh"><div class="wp-block-cover__image-background wp-image-324 size-full has-parallax" style="background-position:85% 62%;background-image:url(https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg)"></div><span aria-hidden="true" class="wp-block-cover__background has-white-background-color has-background-dim"></span><div class="wp-block-cover__inner-container"><!-- wp:group {"className":"group","style":{"css":".pagelayer-col-holder .formlayer-form label { color: #000 !important; }"},"layout":{"type":"constrained","justifyContent":"center"}} -->\n<div class="wp-block-group group has-custom-css"><!-- wp:pagelayer/pl-col {"content_pos":"flex-start","col":"10","overlay_type":"color","overlay_gradient":"180,#44d3f6,23,#72e584,45,#2ca4eb,100","overlay_transperancy":0.2,"ele_scrolling_effects":"true","ele_vertical_scroll":"true","ele_transparency":"true","ele_transp_level":5.3,"pagelayer-id":"mo79050"} -->\n<!-- wp:heading {"level":3,"className":"animated fadeIn","style":{"typography":{"fontStyle":"normal","fontWeight":"600"}}} -->\n<h3 class="wp-block-heading animated fadeIn" style="font-style:normal;font-weight:600">Let''s Connect</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"className":"animated fadeIn","style":{"typography":{"lineHeight":1.6,"fontSize":"20px"}}} -->\n<p class="animated fadeIn" style="font-size:20px;line-height:1.6">If you’re looking for a dedicated, technically savvy, and creatively driven professional to bring your video or photography project to life, whether it is a live event, a corporate interview, or a global brand campaign, let’s connect and start a conversation.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {"className":"animated fadeIn formGroup","layout":{"type":"constrained"}} -->\n<div class="wp-block-group animated fadeIn formGroup"><!-- wp:shortcode -->\n[formlayer id="1"]\n<!-- /wp:shortcode --></div>\n<!-- /wp:group -->\n<!-- /wp:pagelayer/pl-col --></div>\n<!-- /wp:group --></div></div>\n<!-- /wp:cover -->', 'About David', '', 'inherit', 'closed', 'closed', '', '372-revision-v1', '', '', '2026-05-31 13:08:28', '2026-05-31 17:08:28', '', 372, 'https://davidkausek.com/?p=573', 0, 'revision', '', 0),
