(588, 1, '2026-05-31 13:41:24', '2026-05-31 17:41:24', '<!-- wp:media-text {"align":"full","mediaPosition":"right","mediaId":538,"mediaLink":"https://davidkausek.com/davidk-systems/","linkDestination":"none","mediaType":"image","mediaWidth":60,"verticalAlignment":"top","imageFill":false,"metadata":{"categories":["banner"],"patternName":"event","name":"Event"},"style":{"color":{"background":"#121c1c","text":"#fffdc7"},"elements":{"link":{"color":{"text":"#fffdc7"}}}}} -->\n<div class="wp-block-media-text alignfull has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-top has-text-color has-background has-link-color" style="color:#fffdc7;background-color:#121c1c;grid-template-columns:auto 60%"><div class="wp-block-media-text__content"></div><figure class="wp-block-media-text__media"><img src="https://davidkausek.com/wp-content/uploads/2026/05/davidk-systems.jpeg" alt="David Kausek on set" class="wp-image-538 size-full"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:cover {"customOverlayColor":"#ffffff","isUserOverlayColor":true,"minHeight":100,"minHeightUnit":"vh","contentPosition":"center center","isDark":false,"metadata":{"categories":["banner"],"patternName":"core/media-and-text-in-a-full-height-container","name":"Media and text in a full height container"},"align":"full"} -->\n<div class="wp-block-cover alignfull is-light" style="min-height:100vh"><span aria-hidden="true" class="wp-block-cover__background has-background-dim-100 has-background-dim" style="background-color:#ffffff"></span><div class="wp-block-cover__inner-container"><!-- wp:media-text {"align":"wide","mediaLink":"https://s.w.org/images/core/5.8/soil.jpg","mediaType":"image","mediaWidth":56,"verticalAlignment":"center","imageFill":true} -->\n<div class="wp-block-media-text alignwide is-stacked-on-mobile is-vertically-aligned-center is-image-fill-element" style="grid-template-columns:56% auto"><figure class="wp-block-media-text__media"><img src="https://s.w.org/images/core/5.8/soil.jpg" alt="Close-up of dried, cracked earth." style="object-position:50% 50%"/></figure><div class="wp-block-media-text__content"><!-- wp:heading {"style":{"typography":{"fontSize":"32px"},"color":{"text":"#000000"}}} -->\n<h2 class="wp-block-heading has-text-color" style="color:#000000;font-size:32px"><strong>What''s the problem?</strong></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"fontSize":"17px"},"color":{"text":"#000000"}}} -->\n<p class="has-text-color" style="color:#000000;font-size:17px">Trees are more important today than ever before. More than 10,000 products are reportedly made from trees. Through chemistry, the humble woodpile is yielding chemicals, plastics and fabrics that were beyond comprehension when an axe first felled a Texas tree.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons -->\n<div class="wp-block-buttons"><!-- wp:button {"className":"is-style-fill"} -->\n<div class="wp-block-button is-style-fill"><a class="wp-block-button__link wp-element-button">Learn more</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div></div>\n<!-- /wp:media-text --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:media-text {"align":"full","mediaPosition":"right","mediaLink":"#","mediaType":"image","mediaWidth":56,"verticalAlignment":"center","className":"is-style-default"} -->\n<div class="wp-block-media-text alignfull has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-center is-style-default" style="grid-template-columns:auto 56%"><div class="wp-block-media-text__content"><!-- wp:post-title {"style":{"elements":{"link":{"color":{"text":"var:preset|color|custom-link-red"}}},"spacing":{"margin":{"bottom":"0px","right":"var:preset|spacing|60"},"padding":{"bottom":"0px"}}},"textColor":"custom-link-red"} /-->\n\n<!-- wp:heading {"level":4,"className":"animated fadeIn","style":{"typography":{"textAlign":"left"},"spacing":{"padding":{"right":"1vw"}}}} -->\n<h4 class="wp-block-heading has-text-align-left animated fadeIn" sty