:"left"}} -->\n<!-- wp:query-pagination-previous {"label":"Previous","style":{"typography":{"textTransform":"uppercase"}},"fontSize":"small"} /-->\n\n<!-- wp:query-pagination-next {"label":"Next","style":{"typography":{"textTransform":"uppercase"}},"fontSize":"small"} /-->\n<!-- /wp:query-pagination --></div>\n<!-- /wp:group --></div>\n<!-- /wp:query --></main>\n<!-- /wp:group -->\n\n<!-- wp:post-content /-->\n\n<!-- wp:pagelayer/pl-post-nav {"pagelayer-id":"4yf3312"} /-->\n\n<!-- wp:spacer -->\n<div style="height:100px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:template-part {"slug":"footer","theme":"davidk-theme","tagName":"footer"} /-->', 'Single Posts', 'Displays a single post on your website unless a custom template has been applied to that post or a dedicated template exists.', 'inherit', 'closed', 'closed', '', '114-revision-v1', '', '', '2026-07-22 12:05:52', '2026-07-22 16:05:52', '', 114, 'https://davidkausek.com/?p=676', 0, 'revision', '', 0),
