(991, 1, '2026-07-23 19:57:54', '2026-07-23 23:57:54', '<!-- wp:template-part {"slug":"header","theme":"davidk-theme","area":"header"} /-->\n\n<!-- wp:spacer {"height":"1em"} -->\n<div style="height:1em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {"style":{"spacing":{"padding":{"top":"2em"}}},"backgroundColor":"custom-darker-gray"} -->\n<div class="wp-block-columns has-custom-darker-gray-background-color has-background" style="padding-top:2em"><!-- wp:column {"className":"animated fadeIn delay-100ms slow"} -->\n<div class="wp-block-column animated fadeIn delay-100ms slow"><!-- wp:query {"queryId":35,"query":{"perPage":1,"pages":0,"offset":0,"postType":"post","order":"desc","orderBy":"date","author":"","search":"","exclude":[],"sticky":"only","inherit":false},"metadata":{"categories":["posts"],"patternName":"core/query-medium-posts","name":"Image at left"}} -->\n<div class="wp-block-query"><!-- wp:post-template {"style":{"color":{"background":"#32373d"},"border":{"radius":{"topLeft":"0px","topRight":"0px","bottomLeft":"0px","bottomRight":"0px"}},"spacing":{"blockGap":"0em"}}} -->\n<!-- wp:columns {"align":"wide"} -->\n<div class="wp-block-columns alignwide"><!-- wp:column {"width":"","className":"animated fadeIn slow","style":{"spacing":{"padding":{"top":"0em","bottom":"2em"}}}} -->\n<div class="wp-block-column animated fadeIn slow" style="padding-top:0em;padding-bottom:2em"><!-- wp:post-featured-image {"isLink":true,"aspectRatio":"auto","width":"","height":"60vh","sizeSlug":"full","className":"animated fadeIn slow"} /-->\n\n<!-- wp:group {"style":{"spacing":{"padding":{"right":"1em","left":"1em"}}},"layout":{"type":"constrained"}} -->\n<div class="wp-block-group" style="padding-right:1em;padding-left:1em"><!-- wp:post-title {"isLink":true,"className":"animated fadeIn slow","style":{"typography":{"fontStyle":"normal","fontWeight":"400","lineHeight":"1.2"},"spacing":{"padding":{"top":"0.5em"}}}} /-->\n\n<!-- wp:post-excer