(1127, 2, '2026-07-24 12:22:09', '2026-07-24 16:22:09', '<!-- wp:post-title /-->\n\n<!-- wp:breadcrumbs /-->\n\n<!-- wp:spacer {"height":"1em"} -->\n<div style="height:1em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:pagelayer/pl-grid-gallery {"ids":[210,209,211,208,1123,1125],"columns":"3","col_gap":8,"row_gap":8,"size":"full","pagelayer-id":"td57380","tmpAtts":{"ids-urls":{"i210":"https://davidkausek.com/wp-content/uploads/2026/05/nature03-scaled.jpg","i209":"https://davidkausek.com/wp-content/uploads/2026/05/nature02-scaled.jpg","i211":"https://davidkausek.com/wp-content/uploads/2026/05/nature04-scaled.jpg","i208":"https://davidkausek.com/wp-content/uploads/2026/05/nature01-scaled.jpg","i1123":"https://davidkausek.com/wp-content/uploads/2026/07/reflectingTree-scaled.jpg","i1125":"https://davidkausek.com/wp-content/uploads/2026/07/meditativeRock-scaled.jpeg"},"ids-all-urls":{"i210":{"thumbnail":"https://davidkausek.com/wp-content/uploads/2026/05/nature03-150x150.jpg","medium":"https://davidkausek.com/wp-content/uploads/2026/05/nature03-300x225.jpg","large":"https://davidkausek.com/wp-content/uploads/2026/05/nature03-1024x768.jpg","full":"https://davidkausek.com/wp-content/uploads/2026/05/nature03-scaled.jpg"},"i209":{"thumbnail":"https://davidkausek.com/wp-content/uploads/2026/05/nature02-150x150.jpg","medium":"https://davidkausek.com/wp-content/uploads/2026/05/nature02-225x300.jpg","large":"https://davidkausek.com/wp-content/uploads/2026/05/nature02-768x1024.jpg","full":"https://davidkausek.com/wp-content/uploads/2026/05/nature02-scaled.jpg"},"i211":{"thumbnail":"https://davidkausek.com/wp-content/uploads/2026/05/nature04-150x150.jpg","medium":"https://davidkausek.com/wp-content/uploads/2026/05/nature04-300x225.jpg","large":"https://davidkausek.com/wp-content/uploads/2026/05/nature04-1024x768.jpg","full":"https://davidkausek.com/wp-content/uploads/2026/05/nature04-scaled.jpg"},"i208":{"thumbnail":"https://davidkausek.com/wp-content/uploads/2026/05/nature01-150x150.jpg","medium":"https://davidkausek.com/wp-content/uploads/2026/05/nature01-225x300.jpg","large":"https://davidkausek.com/wp-content/uploads/2026/05/nature01-768x1024.jpg","full":"https://davidkausek.com/wp-content/uploads/2026/05/nature01-scaled.jpg"},"i1123":{"thumbnail":"https://davidkausek.com/wp-content/uploads/2026/07/reflectingTree-150x150.jpg","medium":"https://davidkausek.com/wp-content/uploads/2026/07/reflectingTree-225x300.jpg","large":"https://davidkausek.com/wp-content/uploads/2026/07/reflectingTree-768x1024.jpg","full":"https://davidkausek.com/wp-content/uploads/2026/07/reflectingTree-scaled.jpg"},"i1125":{"thumbnail":"https://davidkausek.com/wp-content/uploads/2026/07/meditativeRock-150x150.jpeg","medium":"https://davidkausek.com/wp-content/uploads/2026/07/meditativeRock-240x300.jpeg","large":"https://davidkausek.com/wp-content/uploads/2026/07/meditativeRock-819x1024.jpeg","full":"https://davidkausek.com/wp-content/uploads/2026/07/meditativeRock-scaled.jpeg"}},"ids-all-links":{"i210":"https://davidkausek.com/nature03/","i209":"https://davidkausek.com/nature02/","i211":"https://davidkausek.com/nature04/","i208":"https://davidkausek.com/nature01/","i1123":"https://davidkausek.com/reflectingtree/","i1125":"https://davidkausek.com/meditativerock/"},"ids-all-titles":[],"ids-all-captions":{"i210":"","i209":"","i211":"","i208":"","i1123":"","i1125":""},"gallery-random-id":"gallery-id-67"}} /-->', 'Nature', '', 'inherit', 'closed', 'closed', '', '122-revision-v1', '', '', '2026-07-24 12:22:09', '2026-07-24 16:22:09', '', 122, 'https://davidkausek.com/?p=1127', 0, 'revision', '', 0),
(1128, 2, '2026-07-24 13:25:16', '2026-07-24 17:25:16', '<!-- wp:paragraph {"style":{"elements":{"link":{"color":{"text":"var:preset|color|pale-cyan-blue"}}},"typography":{"textAlign":"center"}},"textColor":"pale-cyan-blue"} -->\n<p class="has-text-align-center has-pale-cyan-blue-color has-text-color has-link-color">Born among a digital paradigm shift<br>There lives a child with curious eyes<br>A spirit full of love and surprise<br><br>Her smile like the rising sun<br>A golden glow upon the horizon<br>Illuminates the Earth<br><br>Her eyes like diamonds glimmering with the ocean<br>Filling the world with vibrant colors<br>An artist with an effortless brush<br><br>Her laugh sings through the valleys of joy<br>Reminding us of the moment of our own birth<br>The wonders of life ever-present in distant memories<br><br>Her skin as sweet as the color of honey<br><br>This rainbow child, a life <br>Sings the song of cosmic angels <br>Her melody reminding us to look beyond the tragedy of death <br>And all those dreams that could have been<br><br>For all the unborn souls who faded too soon…<br><br>A moment of silence….<br><br>Those “little beans” that brought great joy <br>Before dying like the embers of a fire extinguished by violent rain <br>Bringing tears that flowed from the mountains <br>Washing away the pain and grief <br>A silent suffering shared by many <br>A taboo to speak the truth<br><br>With resonant sounds <br>The words sung with meaning <br>Reminds us of what it means to be human<br><br>This beautiful rainbow child shines bright against the darkest of skies <br>In a world of hope and a world of lies <br>Her majestic smile has the power to melt the ice of the coldest adult hearts<br><br>This child looks up at the fresh blue sky <br>Not knowing the cycles before her <br>All is full of wonder and curiosity <br>A reflection of our innermost being<br><br>With clarity <br>A beam of light <br>Parts the fog of modern distortions<br><br>The child can be heard across the land <br>Echoing the potentialities of what “can become” <br>The future grasped by little hands <br>So warm and loving <br>As fragile as a falling snowflake <br>Blanketing the forest filled with birds<br><br>This infant, an ember in our hearts <br>Gazes upon the world with wonder and delight <br>Her smile is such an amazing sight <br>A divine beauty beyond words <br>Fills our mouth with silence <br>There are no words to express this feeling<br><br>We walk a path altered by new decisions <br>A journey traveled by our ancestors<br><br>Angelic spirits of light <br>Caress the faces of innocent beings<br><br>A fragrant wind <br>A lotus unfolds on the surface of a still lake <br>The most ancient mirror<br><br>A message in a bottle <br>Drifting towards us with magnetic force <br>What words were they trying to form? <br>A vibration of the soul <br>A gift from beyond<br><br>This parallel reality <br>Full of dimension <br>Time and space<br><br>We gaze upon the clear blue skies <br>With an obscure reminder of the most obscene <br>The most ancient cycles.. <br>All that lives must die <br>(Rebirth)<br><br>The sun shown bright <br>A moon circling the sphere<br><br>This cosmic song of the universe cannot be recorded<br><br>Only experienced directly <br>Through the subtle lens of observation<br><br>The curiosity of the mind <br>Reflects the truth of our being<br><br>The child shines bright <br>With tears of joy and delight<br><br>With the purity of heart, <br>Her voice can be heard </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {"style":{"elements":{"link":{"color":{"text":"var:preset|color|pale-cyan-blue"}}},"typography":{"textAlign":"center"}},"textColor":"pale-cyan-blue"} -->\n<p class="has-text-align-center has-pale-cyan-blue-color has-text-color has-link-color"><br>A landscape <br>A canvas <br>A child of art<br><br>Isobel Anaya <br>Daddy loves you forever and always <br>An eternal flame<br></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {"style":{"typography":{"textAlign":"right"}}} -->\n<p class="has-text-align-right"><br><br>Original poem by David Kausek</p>\n<!-- /wp:paragraph -->', 'This curious child gazes skyward', '', 'inherit', 'closed', 'closed', '', '818-revision-v1', '', '', '2026-07-24 13:25:16', '2026-07-24 17:25:16', '', 818, 'https://davidkausek.com/?p=1128', 0, 'revision', '', 0),
