(1429, 1, '2026-07-26 23:11:37', '2026-07-27 03:11:37', 'a.wp-block-navigation-item__content:hover { color: #ff3737 !important; }\n:where(.wp-site-blocks) > * { margin-block-start: 0px; }\n.formlayer-form { max-width: 700px; }\n/*Form styles for dark bg*/\n.formlayer-form label, \n.formlayer-options-list .formlayer-option-label span, .lightForm .formlayer-section-break h3 { color: #fff !important; }\n/* Form styles for light bg*/\n.formGroup .formlayer-form label, .formGroup .formlayer-help-text,\n.formGroup .formlayer-option-label span { color: #000 !important; }\n/*General form styles*/\n.formlayer-form label { font-weight: 400 !important; font-size: 1em !important; }\n.formlayer-options-list .formlayer-option-label span { font-size: 1em !important; }\n.formlayer-submit-btn { background: #32373c !important; font-weight: 400 !important; font-family: Urbanist; font-size: 1em !important; }\n.formlayer-submit-btn:hover {background-color:orange !important;color:#000 !important;box-shadow:none !important;}\ntextarea.formlayer-input  { font-family: arial; }\n.formlayer-form-fields-wrapper .formlayer-section-break h3 {\n	font-size: 1.5em !important;\n	font-weight: normal !important;\n}\n/* Force Pagelayer Grid Gallery to stack on mobile */\n@media (max-width: 768px) {\n    .pagelayer-grid-gallery-ul {\n        display:block !important;\n    }\n.pagelayer-gallery-item { padding: 16px 8px !important;}\n}\n/* Mobile specific*/\n@media (max-width: 599px) {\n/* Remove padding from mobile nav*/\n	.wp-block-template-part .wp-block-group.is-layout-flow.wp-block-group-is-layout-flow {\n	padding-top: 0px !important;\n	padding-bottom: 0px !important;\n }\n	.wp-block-navigation__responsive-container-open svg, .wp-block-navigation-overlay-close svg {\n	width: 48px !important;\n	height: 48px !important;\n }\n/* Keeps the desktop header menu text standard */\n.wp-block-navigation:not(.is-menu-open) .wp-block-navigation-item {\n    font-size: 16px; \n}\n\n/* Forces the mobile overlay menu text to be larger */\n.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation-item {\n    font-size: 26px !important;\n    line-height: 1.5;\n}\n/* Subheader mobile styles */\n	.subpageHeader, #packages {\n		padding-left: 7vw !important;\n		padding-right: 7vw !important;\n	}\n	.subpageHeader p {\n		font-size: 26px !important;\n		line-height: 43px !important;\n	}\n	#contactFormSection {\n		padding-top: 0em !important;\n    padding-bottom: 2em !important;\n	}\n	.myReelHeader h2 {\n		padding-left: 11vw !important;\n	}\n}\n/* Additional padding for Blog home right col*/\n@media (min-width: 782px) {\n.extraColPadding {\n	padding-left: 1.5em;\n	padding-right: 1em;\n	}\nh2.extraColPadding {\n	padding-left: .6em !important;\n	}\n}', 'davidk-theme', '', 'inherit', 'closed', 'closed', '', '167-revision-v1', '', '', '2026-07-26 23:11:37', '2026-07-27 03:11:37', '', 167, 'https://davidkausek.com/?p=1429', 0, 'revision', '', 0),
