(1487, 1, '2026-07-27 16:41:30', '2026-07-27 20:41:30', '<!-- wp:cover {"url":"https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg","id":324,"alt":"Photo David Kausek holding camera on the beach in winter","hasParallax":true,"dimRatio":10,"customOverlayColor":"#9d9996","isUserOverlayColor":false,"minHeight":100,"minHeightUnit":"vh","contentPosition":"center center","isDark":false,"sizeSlug":"full","metadata":{"blockVisibility":{"viewport":{"mobile":false}}},"align":"full","style":{"spacing":{"margin":{"bottom":"-24px"}}},"layout":{"type":"default"}} -->\n<div class="wp-block-cover alignfull is-light has-parallax" style="margin-bottom:-24px;min-height:100vh"><div role="img" aria-label="Photo David Kausek holding camera on the beach in winter" class="wp-block-cover__image-background wp-image-324 size-full has-parallax" style="background-position:50% 50%;background-image:url(https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg)"></div><span aria-hidden="true" class="wp-block-cover__background has-background-dim-10 has-background-dim" style="background-color:#9d9996"></span><div class="wp-block-cover__inner-container"><!-- wp:columns {"style":{"spacing":{"padding":{"right":"var:preset|spacing|80"}}}} -->\n<div class="wp-block-columns" style="padding-right:var(--wp--preset--spacing--80)"><!-- wp:column {"width":"45.95%"} -->\n<div class="wp-block-column" style="flex-basis:45.95%"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"width":"50%"} -->\n<div class="wp-block-column" style="flex-basis:50%"><!-- wp:group {"layout":{"type":"flex","flexWrap":"nowrap","justifyContent":"right","verticalAlignment":"top"}} -->\n<div class="wp-block-group"><!-- wp:pagelayer/pl-col {"content_pos":"flex-end","col":"7","overlay_state":"","overlay_type":"color","overlay_gradient":"180,#44d3f6,23,#72e584,45,#2ca4eb,100","overlay_transperancy":0.2,"overlay_type_hover":"color","overlay_color_hover":"","ele_scrolling_effects":"true","ele_vertical_scroll":"true","ele_transparency":"true","ele_transp_level":5.3,"pagelayer-id":"lih4809"} -->\n<!-- wp:heading {"level":1,"style":{"typography":{"fontStyle":"normal","fontWeight":"500"},"spacing":{"margin":{"bottom":"0.2em"}}}} -->\n<h1 class="wp-block-heading" style="margin-bottom:0.2em;font-style:normal;font-weight:500"><o-anim-typing>About David</o-anim-typing></h1>\n<!-- /wp:heading -->\n\n<!-- wp:heading {"className":"animated fadeIn slow","style":{"typography":{"fontStyle":"normal","fontWeight":"300","fontSize":"1.6em","lineHeight":"1.7","letterSpacing":"1px"},"color":{"background":"#ffffff8f"},"border":{"radius":{"topLeft":"12px","topRight":"12px","bottomLeft":"12px","bottomRight":"12px"}},"spacing":{"padding":{"right":"1.5em","left":"1.5em"}}},"fontFamily":"system-font"} -->\n<h2 class="wp-block-heading animated fadeIn slow has-background has-system-font-font-family" style="border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-left-radius:12px;border-bottom-right-radius:12px;background-color:#ffffff8f;padding-right:1.5em;padding-left:1.5em;font-size:1.6em;font-style:normal;font-weight:300;letter-spacing:1px;line-height:1.7">I began my career in 2006, stepping into the world of professional videography and photography with a clear vision: to capture moments that matter and tell stories that resonate.<br><br>I enjoy working in Manhattan and the tri-state area. I also travel to set up and manage shoots in Los Angeles, London, Washington, DC, Puerto Rico and anywhere else the client is based.</h2>\n<!-- /wp:heading -->\n<!-- /wp:pagelayer/pl-col --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {"height":"3em","width":"0px","metadata":{"blockVisibility":{"viewport":{"tablet":false,"mobile":false}}},"style":{"layout":[]}} -->\n<div style="height:3em;width:0px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:media-text {"align":"full","mediaPosition":"right","mediaId":324,"mediaLink":"https://davidkausek.com/david-camera-4/","linkDestination":"none","mediaType":"image","mediaWidth":60,"mediaSizeSlug":"full","verticalAlignment":"top","imageFill":true,"metadata":{"categories":["banner"],"patternName":"event","name":"Event","blockVisibility":{"viewport":{"desktop":false,"tablet":false}}},"className":"animated fadeIn slow","style":{"elements":{"link":{"color":{"text":"#f97f28"}}},"spacing":{"margin":{"top":"0","bottom":"0","left":"0em","right":"0em"}}},"backgroundColor":"black","textColor":"white"} -->\n<div class="wp-block-media-text alignfull has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-top is-image-fill-element animated fadeIn slow has-white-color has-black-background-color has-text-color has-background has-link-color" style="margin-top:0;margin-right:0em;margin-bottom:0;margin-left:0em;grid-template-columns:auto 60%"><div class="wp-block-media-text__content"><!-- wp:group {"style":{"spacing":{"padding":{"top":"3em","right":"0em","bottom":"4em","left":"0em"}}}} -->\n<div class="wp-block-group" style="padding-top:3em;padding-right:0em;padding-bottom:4em;padding-left:0em"><!-- wp:heading {"className":"animated fadeIn slow","style":{"typography":{"fontWeight":"500","lineHeight":"1.15","fontStyle":"normal","textTransform":"capitalize"},"elements":{"link":{"color":{"text":"var:preset|color|custom-grey-blue"}}}},"textColor":"custom-grey-blue"} -->\n<h2 class="wp-block-heading animated fadeIn slow has-custom-grey-blue-color has-text-color has-link-color" style="font-style:normal;font-weight:500;line-height:1.15;text-transform:capitalize"><o-anim-typing>About David</o-anim-typing></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slower","style":{"typography":{"lineHeight":1.6,"fontStyle":"normal","fontWeight":"300","fontSize":"1.5em","letterSpacing":"1px"}},"fontFamily":"system-font"} -->\n<p class="animated fadeIn slower has-system-font-font-family" style="font-size:1.5em;font-style:normal;font-weight:300;letter-spacing:1px;line-height:1.6">I began my career in 2006, stepping into the world of professional videography and photography with a clear vision: to capture moments that matter and tell stories that resonate. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slower","style":{"typography":{"lineHeight":1.6,"fontStyle":"normal","fontWeight":"300","fontSize":"1.5em","letterSpacing":"1px"}},"fontFamily":"system-font"} -->\n<p class="animated fadeIn slower has-system-font-font-family" style="font-size:1.5em;font-style:normal;font-weight:300;letter-spacing:1px;line-height:1.6">I enjoy working in Manhattan and the tri-state area. I also travel to set up and manage shoots in Los Angeles, London, Washington, DC, Puerto Rico and anywhere else the client is based.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div><figure class="wp-block-media-text__media"><img src="https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg" alt="Photo David Kausek holding camera on the beach in winter" class="wp-image-324 size-full" style="object-position:50% 50%"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:columns {"style":{"spacing":{"blockGap":{"left":"0em"}},"color":{"background":"#32373d"}}} -->\n<div class="wp-block-columns has-background" style="background-color:#32373d"><!-- wp:column {"width":"100%","style":{"spacing":{"blockGap":"0em"}}} -->\n<div class="wp-block-column" style="flex-basis:100%"><!-- wp:spacer {"height":"3em","width":"0px","metadata":{"blockVisibility":{"viewport":{"tablet":false,"mobile":false}}},"style":{"layout":[]}} -->\n<div style="height:3em;width:0px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {"level":3,"className":"animated fadeIn slow","style":{"spacing":{"padding":{"top":"var:preset|spacing|50","bottom":"0.5em"}},"typography":{"fontStyle":"normal","fontWeight":"500"}}} -->\n<h3 class="wp-block-heading animated fadeIn slow" style="padding-top:var(--wp--preset--spacing--50);padding-bottom:0.5em;font-style:normal;font-weight:500">What I do</h3>\n<!-- /wp:heading -->\n\n<!-- wp:columns {"style":{"spacing":{"blockGap":{"left":"2em"}}}} -->\n<div class="wp-block-columns"><!-- wp:column {"verticalAlignment":"stretch","width":"100%","className":"animated fadeIn slow","style":{"border":{"radius":{"topLeft":"0px","topRight":"0px","bottomLeft":"0px","bottomRight":"0px"}}}} -->\n<div class="wp-block-column is-vertically-aligned-stretch animated fadeIn slow" style="border-top-left-radius:0px;border-top-right-radius:0px;border-bottom-left-radius:0px;border-bottom-right-radius:0px;flex-basis:100%"><!-- wp:group {"style":{"spacing":{"padding":{"right":"0","left":"0","top":"1.5em","bottom":"1.5em"}},"typography":{"fontSize":"18px"}},"layout":{"type":"default"}} -->\n<div class="wp-block-group" style="padding-top:1.5em;padding-right:0;padding-bottom:1.5em;padding-left:0;font-size:18px"><!-- wp:heading {"level":4,"className":"animated fadeIn slow","style":{"typography":{"fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading animated fadeIn slow" style="margin-bottom:0;font-style:normal;font-weight:400">Livestream Technical Director</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow","style":{"typography":{"lineHeight":1.6}}} -->\n<p class="animated fadeIn slow" style="line-height:1.6">I engineer, produce, and manage virtual and hybrid video broadcasts that keep audiences engaged in real time. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {"layout":{"type":"constrained"}} -->\n<div class="wp-block-group"><!-- wp:accordion -->\n<div role="group" class="wp-block-accordion"><!-- wp:accordion-item -->\n<div class="wp-block-accordion-item"><!-- wp:accordion-heading {"className":"animated fadeIn slow","style":{"typography":{"fontSize":"1.3em","fontStyle":"italic","fontWeight":"400"}}} -->\n<h3 class="wp-block-accordion-heading animated fadeIn slow" style="font-size:1.3em;font-style:italic;font-weight:400"><button type="button" class="wp-block-accordion-heading__toggle"><span class="wp-block-accordion-heading__toggle-title">How I execute it</span><span class="wp-block-accordion-heading__toggle-icon" aria-hidden="true">+</span></button></h3>\n<!-- /wp:accordion-heading -->\n\n<!-- wp:accordion-panel -->\n<div role="region" class="wp-block-accordion-panel"><!-- wp:paragraph -->\n<p>I build robust, scalable streaming solutions using professional cinema cameras, PTZ systems, VLAN, NDI, 4‑ME TD, and broadcast‑grade video networking systems. From signal routing to on‑the‑fly troubleshooting, I ensure a flawless livestream experience.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:accordion-panel --></div>\n<!-- /wp:accordion-item --></div>\n<!-- /wp:accordion --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"verticalAlignment":"stretch","width":"100%","className":"animated fadeIn delay-200ms slow","style":{"border":{"radius":{"topLeft":"8px","topRight":"8px","bottomLeft":"8px","bottomRight":"8px"}}}} -->\n<div class="wp-block-column is-vertically-aligned-stretch animated fadeIn delay-200ms slow" style="border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px;flex-basis:100%"><!-- wp:group {"style":{"spacing":{"padding":{"right":"0","left":"0","top":"1.5em","bottom":"1.5em"}},"typography":{"fontSize":"18px"}},"layout":{"type":"default"}} -->\n<div class="wp-block-group" style="padding-top:1.5em;padding-right:0;padding-bottom:1.5em;padding-left:0;font-size:18px"><!-- wp:heading {"level":4,"className":"animated fadeIn slow","style":{"typography":{"fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading animated fadeIn slow" style="margin-bottom:0;font-style:normal;font-weight:400">Director of Photography (DP)</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow","style":{"typography":{"lineHeight":1.6}}} -->\n<p class="animated fadeIn slow" style="line-height:1.6">I lead the camera and lighting crews to translate a creative vision into striking visual imagery.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {"layout":{"type":"constrained"}} -->\n<div class="wp-block-group"><!-- wp:accordion -->\n<div role="group" class="wp-block-accordion"><!-- wp:accordion-item -->\n<div class="wp-block-accordion-item"><!-- wp:accordion-heading {"className":"animated fadeIn slow","style":{"typography":{"fontSize":"1.3em","fontStyle":"italic","fontWeight":"400"}}} -->\n<h3 class="wp-block-accordion-heading animated fadeIn slow" style="font-size:1.3em;font-style:italic;font-weight:400"><button type="button" class="wp-block-accordion-heading__toggle"><span class="wp-block-accordion-heading__toggle-title">How I execute it</span><span class="wp-block-accordion-heading__toggle-icon" aria-hidden="true">+</span></button></h3>\n<!-- /wp:accordion-heading -->\n\n<!-- wp:accordion-panel -->\n<div role="region" class="wp-block-accordion-panel"><!-- wp:paragraph -->\n<p>I collaborate with directors, designers, and clients to devise creative lighting plans, talent positions and camera setups. On set, I coordinate the team, make real‑time creative decisions, and keep the production on schedule and on budget.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:accordion-panel --></div>\n<!-- /wp:accordion-item --></div>\n<!-- /wp:accordion --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"verticalAlignment":"stretch","width":"100%","className":"animated fadeIn delay-500ms slow","style":{"border":{"radius":{"topLeft":"8px","topRight":"8px","bottomLeft":"8px","bottomRight":"8px"}}}} -->\n<div class="wp-block-column is-vertically-aligned-stretch animated fadeIn delay-500ms slow" style="border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px;flex-basis:100%"><!-- wp:group {"style":{"spacing":{"padding":{"right":"0","left":"0","top":"1.5em","bottom":"1.5em"}},"typography":{"fontSize":"18px"}},"layout":{"type":"default"}} -->\n<div class="wp-block-group" style="padding-top:1.5em;padding-right:0;padding-bottom:1.5em;padding-left:0;font-size:18px"><!-- wp:heading {"level":4,"className":"animated fadeIn slow","style":{"typography":{"fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading animated fadeIn slow" style="margin-bottom:0;font-style:normal;font-weight:400">Photographer</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow","style":{"typography":{"lineHeight":1.6}}} -->\n<p class="animated fadeIn slow" style="line-height:1.6">I capture still images that complement live video content or stand alone as powerful marketing assets. I also utilize the camera as a creative tool to capture emotion and beauty.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {"layout":{"type":"constrained"}} -->\n<div class="wp-block-group"><!-- wp:accordion -->\n<div role="group" class="wp-block-accordion"><!-- wp:accordion-item -->\n<div class="wp-block-accordion-item"><!-- wp:accordion-heading {"className":"animated fadeIn slow","style":{"typography":{"fontSize":"1.3em","fontStyle":"italic","fontWeight":"400"}}} -->\n<h3 class="wp-block-accordion-heading animated fadeIn slow" style="font-size:1.3em;font-style:italic;font-weight:400"><button type="button" class="wp-block-accordion-heading__toggle"><span class="wp-block-accordion-heading__toggle-title">How I execute it</span><span class="wp-block-accordion-heading__toggle-icon" aria-hidden="true">+</span></button></h3>\n<!-- /wp:accordion-heading -->\n\n<!-- wp:accordion-panel -->\n<div role="region" class="wp-block-accordion-panel"><!-- wp:paragraph -->\n<p>I specialize in live events, corporate portraits, and interviews, using a keen eye for composition, lighting, and storytelling to produce images that enhance the narrative.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:accordion-panel --></div>\n<!-- /wp:accordion-item --></div>\n<!-- /wp:accordion --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {"height":"3em","width":"0px","metadata":{"blockVisibility":{"viewport":{"tablet":false,"mobile":false}}},"style":{"layout":[]}} -->\n<div style="height:3em;width:0px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {"style":{"spacing":{"padding":{"bottom":"0em","top":"4em","right":"2em","left":"2em"}}}} -->\n<div class="wp-block-columns" style="padding-top:4em;padding-right:2em;padding-bottom:0em;padding-left:2em"><!-- wp:column -->\n<div class="wp-block-column"><!-- wp:heading {"level":3,"className":"animated fadeIn slow","style":{"css":"@media (max-width: 768px) {\\n    h3 { font-size: 36px; }\\n}","typography":{"fontStyle":"normal","fontWeight":"400"}}} -->\n<h3 class="wp-block-heading animated fadeIn slow has-custom-css" style="font-style:normal;font-weight:400">My Approach</h3>\n<!-- /wp:heading --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {"style":{"spacing":{"padding":{"top":"1em","bottom":"0em","right":"2em","left":"2em"},"blockGap":{"top":"0","left":"3em"}}}} -->\n<div class="wp-block-columns" style="padding-top:1em;padding-right:2em;padding-bottom:0em;padding-left:2em"><!-- wp:column -->\n<div class="wp-block-column"><!-- wp:paragraph {"className":"animated fadeIn slow","style":{"typography":{"fontSize":"20px"}}} -->\n<p class="animated fadeIn slow" style="font-size:20px"><strong>Creative Problem Solver</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow","style":{"typography":{"fontSize":"20px"}}} -->\n<p class="animated fadeIn slow" style="font-size:20px">I view every technical challenge as an opportunity to innovate, turning potential obstacles into creative solutions.<br><br></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class="wp-block-column"><!-- wp:paragraph {"className":"animated fadeIn slow delay-200ms","style":{"typography":{"fontSize":"20px"}}} -->\n<p class="animated fadeIn slow delay-200ms" style="font-size:20px"><strong>Team‑First Philosophy</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow delay-200ms","style":{"typography":{"fontSize":"20px"}}} -->\n<p class="animated fadeIn slow delay-200ms" style="font-size:20px">Production thrives on collaboration. I work hand‑in‑hand with sound, lighting, post‑production, and creative teams to create a unified workflow that delivers the best possible product for my clients.<br><br></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class="wp-block-column"><!-- wp:paragraph {"className":"animated fadeIn slow delay-500ms","style":{"typography":{"fontSize":"20px"}}} -->\n<p class="animated fadeIn slow delay-500ms" style="font-size:20px"><strong>Global Flexibility</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow delay-500ms","style":{"typography":{"fontSize":"20px"}}} -->\n<p class="animated fadeIn slow delay-500ms" style="font-size:20px">While rooted in New York City, I’m comfortable traveling worldwide to set up and manage shoots wherever the client’s vision requires.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {"height":"3em","width":"0px","style":{"layout":[]}} -->\n<div style="height:3em;width:0px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:cover {"url":"https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg","id":324,"alt":"Photo David Kausek holding camera on the beach in winter","hasParallax":true,"dimRatio":50,"overlayColor":"white","isUserOverlayColor":true,"focalPoint":{"x":0.85,"y":0.62},"minHeight":100,"minHeightUnit":"vh","contentPosition":"top center","isDark":false,"sizeSlug":"full","style":{"spacing":{"margin":{"bottom":"-24px"},"padding":{"right":"0px","left":"0px"}}},"layout":{"type":"default"}} -->\n<div class="wp-block-cover is-light has-parallax has-custom-content-position is-position-top-center" style="margin-bottom:-24px;padding-right:0px;padding-left:0px;min-height:100vh"><div role="img" aria-label="Photo David Kausek holding camera on the beach in winter" class="wp-block-cover__image-background wp-image-324 size-full has-parallax" style="background-position:85% 62%;background-image:url(https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg)"></div><span aria-hidden="true" class="wp-block-cover__background has-white-background-color has-background-dim"></span><div class="wp-block-cover__inner-container"><!-- wp:spacer {"height":"3em","width":"0px","metadata":{"blockVisibility":{"viewport":{"tablet":false,"mobile":false}}},"style":{"layout":[]}} -->\n<div style="height:3em;width:0px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {"style":{"spacing":{"padding":{"top":"1em","bottom":"0em","right":"2em","left":"2em"},"blockGap":{"top":"0","left":"3em"}}}} -->\n<div class="wp-block-columns" style="padding-top:1em;padding-right:2em;padding-bottom:0em;padding-left:2em"><!-- wp:column {"style":{"css":"max-width: 1000px;"},"layout":{"type":"constrained","justifyContent":"center"}} -->\n<div class="wp-block-column has-custom-css"><!-- wp:heading {"level":3,"className":"animated fadeIn slow","style":{"typography":{"fontStyle":"normal","fontWeight":"600","textAlign":"left"}}} -->\n<h3 class="wp-block-heading has-text-align-left animated fadeIn slow" style="font-style:normal;font-weight:600">Let''s Connect</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow","style":{"typography":{"lineHeight":1.6,"fontSize":"20px","textAlign":"left"}}} -->\n<p class="has-text-align-left animated fadeIn slow" style="font-size:20px;line-height:1.6">If you''re looking to bring your video or photography project to life, whether it is a live event, a corporate interview, or a global brand campaign, let’s connect and start a conversation.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {"className":"animated fadeIn formGroup slow","layout":{"type":"constrained","justifyContent":"center"}} -->\n<div class="wp-block-group animated fadeIn formGroup slow"><!-- wp:shortcode -->\n[formlayer id="2"]\n<!-- /wp:shortcode --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {"height":"3em","width":"0px","metadata":{"blockVisibility":{"viewport":{"tablet":false,"mobile":false}}},"style":{"layout":[]}} -->\n<div style="height:3em;width:0px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div></div>\n<!-- /wp:cover -->', 'About David', '', 'inherit', 'closed', 'closed', '', '372-revision-v1', '', '', '2026-07-27 16:41:30', '2026-07-27 20:41:30', '', 372, 'https://davidkausek.com/?p=1487', 0, 'revision', '', 0),
(1489, 1, '2026-07-27 16:45:14', '2026-07-27 20:45:14', '<!-- wp:cover {"url":"https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg","id":324,"alt":"Photo David Kausek holding camera on the beach in winter","hasParallax":true,"dimRatio":10,"customOverlayColor":"#9d9996","isUserOverlayColor":false,"minHeight":100,"minHeightUnit":"vh","contentPosition":"center center","isDark":false,"sizeSlug":"full","metadata":{"blockVisibility":{"viewport":{"mobile":false}}},"align":"full","style":{"spacing":{"margin":{"bottom":"-24px"}}},"layout":{"type":"default"}} -->\n<div class="wp-block-cover alignfull is-light has-parallax" style="margin-bottom:-24px;min-height:100vh"><div role="img" aria-label="Photo David Kausek holding camera on the beach in winter" class="wp-block-cover__image-background wp-image-324 size-full has-parallax" style="background-position:50% 50%;background-image:url(https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg)"></div><span aria-hidden="true" class="wp-block-cover__background has-background-dim-10 has-background-dim" style="background-color:#9d9996"></span><div class="wp-block-cover__inner-container"><!-- wp:columns {"style":{"spacing":{"padding":{"right":"var:preset|spacing|80"}}}} -->\n<div class="wp-block-columns" style="padding-right:var(--wp--preset--spacing--80)"><!-- wp:column {"width":"45.95%"} -->\n<div class="wp-block-column" style="flex-basis:45.95%"></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"width":"50%"} -->\n<div class="wp-block-column" style="flex-basis:50%"><!-- wp:group {"layout":{"type":"flex","flexWrap":"nowrap","justifyContent":"right","verticalAlignment":"top"}} -->\n<div class="wp-block-group"><!-- wp:pagelayer/pl-col {"content_pos":"flex-end","col":"7","overlay_state":"","overlay_type":"color","overlay_gradient":"180,#44d3f6,23,#72e584,45,#2ca4eb,100","overlay_transperancy":0.2,"overlay_type_hover":"color","overlay_color_hover":"","ele_scrolling_effects":"true","ele_vertical_scroll":"true","ele_transparency":"true","ele_transp_level":5.3,"pagelayer-id":"lih4809"} -->\n<!-- wp:heading {"level":1,"style":{"typography":{"fontStyle":"normal","fontWeight":"500"},"spacing":{"margin":{"bottom":"0.2em"}}}} -->\n<h1 class="wp-block-heading" style="margin-bottom:0.2em;font-style:normal;font-weight:500"><o-anim-typing>About David</o-anim-typing></h1>\n<!-- /wp:heading -->\n\n<!-- wp:heading {"className":"animated fadeIn slow","style":{"typography":{"fontStyle":"normal","fontWeight":"300","fontSize":"1.6em","lineHeight":"1.7","letterSpacing":"1px"},"color":{"background":"#ffffff8f"},"border":{"radius":{"topLeft":"12px","topRight":"12px","bottomLeft":"12px","bottomRight":"12px"}},"spacing":{"padding":{"right":"1.5em","left":"1.5em"}}},"fontFamily":"system-font"} -->\n<h2 class="wp-block-heading animated fadeIn slow has-background has-system-font-font-family" style="border-top-left-radius:12px;border-top-right-radius:12px;border-bottom-left-radius:12px;border-bottom-right-radius:12px;background-color:#ffffff8f;padding-right:1.5em;padding-left:1.5em;font-size:1.6em;font-style:normal;font-weight:300;letter-spacing:1px;line-height:1.7">I began my career in 2006, stepping into the world of professional videography and photography with a clear vision: to capture moments that matter and tell stories that resonate.<br><br>I enjoy working in Manhattan and the tri-state area. I also travel to set up and manage shoots in Los Angeles, London, Washington, DC, Puerto Rico and anywhere else the client is based.</h2>\n<!-- /wp:heading -->\n<!-- /wp:pagelayer/pl-col --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {"height":"3em","width":"0px","metadata":{"blockVisibility":{"viewport":{"tablet":false,"mobile":false}}},"style":{"layout":[]}} -->\n<div style="height:3em;width:0px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:media-text {"align":"full","mediaPosition":"right","mediaId":324,"mediaLink":"https://davidkausek.com/david-camera-4/","linkDestination":"none","mediaType":"image","mediaWidth":60,"mediaSizeSlug":"full","verticalAlignment":"top","imageFill":true,"metadata":{"categories":["banner"],"patternName":"event","name":"Event","blockVisibility":{"viewport":{"desktop":false,"tablet":false}}},"className":"animated fadeIn slow","style":{"elements":{"link":{"color":{"text":"#f97f28"}}},"spacing":{"margin":{"top":"0","bottom":"0","left":"0em","right":"0em"}}},"backgroundColor":"black","textColor":"white"} -->\n<div class="wp-block-media-text alignfull has-media-on-the-right is-stacked-on-mobile is-vertically-aligned-top is-image-fill-element animated fadeIn slow has-white-color has-black-background-color has-text-color has-background has-link-color" style="margin-top:0;margin-right:0em;margin-bottom:0;margin-left:0em;grid-template-columns:auto 60%"><div class="wp-block-media-text__content"><!-- wp:group {"style":{"spacing":{"padding":{"top":"3em","right":"0em","bottom":"4em","left":"0em"}}}} -->\n<div class="wp-block-group" style="padding-top:3em;padding-right:0em;padding-bottom:4em;padding-left:0em"><!-- wp:heading {"className":"animated fadeIn slow","style":{"typography":{"fontWeight":"500","lineHeight":"1.15","fontStyle":"normal","textTransform":"capitalize"},"elements":{"link":{"color":{"text":"var:preset|color|custom-grey-blue"}}}},"textColor":"custom-grey-blue"} -->\n<h2 class="wp-block-heading animated fadeIn slow has-custom-grey-blue-color has-text-color has-link-color" style="font-style:normal;font-weight:500;line-height:1.15;text-transform:capitalize"><o-anim-typing>About David</o-anim-typing></h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slower","style":{"typography":{"lineHeight":1.6,"fontStyle":"normal","fontWeight":"300","fontSize":"1.5em","letterSpacing":"1px"}},"fontFamily":"system-font"} -->\n<p class="animated fadeIn slower has-system-font-font-family" style="font-size:1.5em;font-style:normal;font-weight:300;letter-spacing:1px;line-height:1.6">I began my career in 2006, stepping into the world of professional videography and photography with a clear vision: to capture moments that matter and tell stories that resonate. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slower","style":{"typography":{"lineHeight":1.6,"fontStyle":"normal","fontWeight":"300","fontSize":"1.5em","letterSpacing":"1px"}},"fontFamily":"system-font"} -->\n<p class="animated fadeIn slower has-system-font-font-family" style="font-size:1.5em;font-style:normal;font-weight:300;letter-spacing:1px;line-height:1.6">I enjoy working in Manhattan and the tri-state area. I also travel to set up and manage shoots in Los Angeles, London, Washington, DC, Puerto Rico and anywhere else the client is based.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div><figure class="wp-block-media-text__media"><img src="https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg" alt="Photo David Kausek holding camera on the beach in winter" class="wp-image-324 size-full" style="object-position:50% 50%"/></figure></div>\n<!-- /wp:media-text -->\n\n<!-- wp:columns {"style":{"spacing":{"blockGap":{"left":"0em"}},"color":{"background":"#32373d"}}} -->\n<div class="wp-block-columns has-background" style="background-color:#32373d"><!-- wp:column {"width":"100%","style":{"spacing":{"blockGap":"0em"}}} -->\n<div class="wp-block-column" style="flex-basis:100%"><!-- wp:spacer {"height":"3em","width":"0px","metadata":{"blockVisibility":{"viewport":{"tablet":false,"mobile":false}}},"style":{"layout":[]}} -->\n<div style="height:3em;width:0px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {"level":3,"className":"animated fadeIn slow","style":{"spacing":{"padding":{"top":"var:preset|spacing|50","bottom":"0.5em"}},"typography":{"fontStyle":"normal","fontWeight":"500"}}} -->\n<h3 class="wp-block-heading animated fadeIn slow" style="padding-top:var(--wp--preset--spacing--50);padding-bottom:0.5em;font-style:normal;font-weight:500">What I do</h3>\n<!-- /wp:heading -->\n\n<!-- wp:columns {"style":{"spacing":{"blockGap":{"left":"2em"}}}} -->\n<div class="wp-block-columns"><!-- wp:column {"verticalAlignment":"stretch","width":"100%","className":"animated fadeIn slow","style":{"border":{"radius":{"topLeft":"0px","topRight":"0px","bottomLeft":"0px","bottomRight":"0px"}}}} -->\n<div class="wp-block-column is-vertically-aligned-stretch animated fadeIn slow" style="border-top-left-radius:0px;border-top-right-radius:0px;border-bottom-left-radius:0px;border-bottom-right-radius:0px;flex-basis:100%"><!-- wp:group {"style":{"spacing":{"padding":{"right":"0","left":"0","top":"1.5em","bottom":"1.5em"}},"typography":{"fontSize":"18px"}},"layout":{"type":"default"}} -->\n<div class="wp-block-group" style="padding-top:1.5em;padding-right:0;padding-bottom:1.5em;padding-left:0;font-size:18px"><!-- wp:heading {"level":4,"className":"animated fadeIn slow","style":{"typography":{"fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading animated fadeIn slow" style="margin-bottom:0;font-style:normal;font-weight:400">Livestream Technical Director</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow","style":{"typography":{"lineHeight":1.6}}} -->\n<p class="animated fadeIn slow" style="line-height:1.6">I engineer, produce, and manage virtual and hybrid video broadcasts that keep audiences engaged in real time. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {"layout":{"type":"constrained"}} -->\n<div class="wp-block-group"><!-- wp:accordion -->\n<div role="group" class="wp-block-accordion"><!-- wp:accordion-item -->\n<div class="wp-block-accordion-item"><!-- wp:accordion-heading {"className":"animated fadeIn slow","style":{"typography":{"fontSize":"1.3em","fontStyle":"italic","fontWeight":"400"}}} -->\n<h3 class="wp-block-accordion-heading animated fadeIn slow" style="font-size:1.3em;font-style:italic;font-weight:400"><button type="button" class="wp-block-accordion-heading__toggle"><span class="wp-block-accordion-heading__toggle-title">How I execute it</span><span class="wp-block-accordion-heading__toggle-icon" aria-hidden="true">+</span></button></h3>\n<!-- /wp:accordion-heading -->\n\n<!-- wp:accordion-panel -->\n<div role="region" class="wp-block-accordion-panel"><!-- wp:paragraph -->\n<p>I build robust, scalable streaming solutions using professional cinema cameras, PTZ systems, VLAN, NDI, 4‑ME TD, and broadcast‑grade video networking systems. From signal routing to on‑the‑fly troubleshooting, I ensure a flawless livestream experience.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:accordion-panel --></div>\n<!-- /wp:accordion-item --></div>\n<!-- /wp:accordion --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"verticalAlignment":"stretch","width":"100%","className":"animated fadeIn delay-200ms slow","style":{"border":{"radius":{"topLeft":"8px","topRight":"8px","bottomLeft":"8px","bottomRight":"8px"}}}} -->\n<div class="wp-block-column is-vertically-aligned-stretch animated fadeIn delay-200ms slow" style="border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px;flex-basis:100%"><!-- wp:group {"style":{"spacing":{"padding":{"right":"0","left":"0","top":"1.5em","bottom":"1.5em"}},"typography":{"fontSize":"18px"}},"layout":{"type":"default"}} -->\n<div class="wp-block-group" style="padding-top:1.5em;padding-right:0;padding-bottom:1.5em;padding-left:0;font-size:18px"><!-- wp:heading {"level":4,"className":"animated fadeIn slow","style":{"typography":{"fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading animated fadeIn slow" style="margin-bottom:0;font-style:normal;font-weight:400">Director of Photography (DP)</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow","style":{"typography":{"lineHeight":1.6}}} -->\n<p class="animated fadeIn slow" style="line-height:1.6">I lead the camera and lighting crews to translate a creative vision into striking visual imagery.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {"layout":{"type":"constrained"}} -->\n<div class="wp-block-group"><!-- wp:accordion -->\n<div role="group" class="wp-block-accordion"><!-- wp:accordion-item -->\n<div class="wp-block-accordion-item"><!-- wp:accordion-heading {"className":"animated fadeIn slow","style":{"typography":{"fontSize":"1.3em","fontStyle":"italic","fontWeight":"400"}}} -->\n<h3 class="wp-block-accordion-heading animated fadeIn slow" style="font-size:1.3em;font-style:italic;font-weight:400"><button type="button" class="wp-block-accordion-heading__toggle"><span class="wp-block-accordion-heading__toggle-title">How I execute it</span><span class="wp-block-accordion-heading__toggle-icon" aria-hidden="true">+</span></button></h3>\n<!-- /wp:accordion-heading -->\n\n<!-- wp:accordion-panel -->\n<div role="region" class="wp-block-accordion-panel"><!-- wp:paragraph -->\n<p>I collaborate with directors, designers, and clients to devise creative lighting plans, talent positions and camera setups. On set, I coordinate the team, make real‑time creative decisions, and keep the production on schedule and on budget.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:accordion-panel --></div>\n<!-- /wp:accordion-item --></div>\n<!-- /wp:accordion --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"verticalAlignment":"stretch","width":"100%","className":"animated fadeIn delay-500ms slow","style":{"border":{"radius":{"topLeft":"8px","topRight":"8px","bottomLeft":"8px","bottomRight":"8px"}}}} -->\n<div class="wp-block-column is-vertically-aligned-stretch animated fadeIn delay-500ms slow" style="border-top-left-radius:8px;border-top-right-radius:8px;border-bottom-left-radius:8px;border-bottom-right-radius:8px;flex-basis:100%"><!-- wp:group {"style":{"spacing":{"padding":{"right":"0","left":"0","top":"1.5em","bottom":"1.5em"}},"typography":{"fontSize":"18px"}},"layout":{"type":"default"}} -->\n<div class="wp-block-group" style="padding-top:1.5em;padding-right:0;padding-bottom:1.5em;padding-left:0;font-size:18px"><!-- wp:heading {"level":4,"className":"animated fadeIn slow","style":{"typography":{"fontStyle":"normal","fontWeight":"400"},"spacing":{"margin":{"bottom":"0"}}}} -->\n<h4 class="wp-block-heading animated fadeIn slow" style="margin-bottom:0;font-style:normal;font-weight:400">Photographer</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow","style":{"typography":{"lineHeight":1.6}}} -->\n<p class="animated fadeIn slow" style="line-height:1.6">I capture still images that complement live video content or stand alone as powerful marketing assets. I also utilize the camera as a creative tool to capture emotion and beauty.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {"layout":{"type":"constrained"}} -->\n<div class="wp-block-group"><!-- wp:accordion -->\n<div role="group" class="wp-block-accordion"><!-- wp:accordion-item -->\n<div class="wp-block-accordion-item"><!-- wp:accordion-heading {"className":"animated fadeIn slow","style":{"typography":{"fontSize":"1.3em","fontStyle":"italic","fontWeight":"400"}}} -->\n<h3 class="wp-block-accordion-heading animated fadeIn slow" style="font-size:1.3em;font-style:italic;font-weight:400"><button type="button" class="wp-block-accordion-heading__toggle"><span class="wp-block-accordion-heading__toggle-title">How I execute it</span><span class="wp-block-accordion-heading__toggle-icon" aria-hidden="true">+</span></button></h3>\n<!-- /wp:accordion-heading -->\n\n<!-- wp:accordion-panel -->\n<div role="region" class="wp-block-accordion-panel"><!-- wp:paragraph -->\n<p>I specialize in live events, corporate portraits, and interviews, using a keen eye for composition, lighting, and storytelling to produce images that enhance the narrative.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:accordion-panel --></div>\n<!-- /wp:accordion-item --></div>\n<!-- /wp:accordion --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {"height":"3em","width":"0px","metadata":{"blockVisibility":{"viewport":{"tablet":false,"mobile":false}}},"style":{"layout":[]}} -->\n<div style="height:3em;width:0px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {"style":{"spacing":{"padding":{"bottom":"0em","top":"4em","right":"2em","left":"2em"}}}} -->\n<div class="wp-block-columns" style="padding-top:4em;padding-right:2em;padding-bottom:0em;padding-left:2em"><!-- wp:column -->\n<div class="wp-block-column"><!-- wp:heading {"level":3,"className":"animated fadeIn slow","style":{"css":"@media (max-width: 768px) {\\n    h3 { font-size: 36px; }\\n}","typography":{"fontStyle":"normal","fontWeight":"400"}}} -->\n<h3 class="wp-block-heading animated fadeIn slow has-custom-css" style="font-style:normal;font-weight:400">My Approach</h3>\n<!-- /wp:heading --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {"style":{"spacing":{"padding":{"top":"1em","bottom":"0em","right":"2em","left":"2em"},"blockGap":{"top":"0","left":"3em"}}}} -->\n<div class="wp-block-columns" style="padding-top:1em;padding-right:2em;padding-bottom:0em;padding-left:2em"><!-- wp:column -->\n<div class="wp-block-column"><!-- wp:paragraph {"className":"animated fadeIn slow","style":{"typography":{"fontSize":"20px"}}} -->\n<p class="animated fadeIn slow" style="font-size:20px"><strong>Creative Problem Solver</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow","style":{"typography":{"fontSize":"20px"}}} -->\n<p class="animated fadeIn slow" style="font-size:20px">I view every technical challenge as an opportunity to innovate, turning potential obstacles into creative solutions.<br><br></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class="wp-block-column"><!-- wp:paragraph {"className":"animated fadeIn slow delay-200ms","style":{"typography":{"fontSize":"20px"}}} -->\n<p class="animated fadeIn slow delay-200ms" style="font-size:20px"><strong>Team‑First Philosophy</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow delay-200ms","style":{"typography":{"fontSize":"20px"}}} -->\n<p class="animated fadeIn slow delay-200ms" style="font-size:20px">Production thrives on collaboration. I work hand‑in‑hand with sound, lighting, post‑production, and creative teams to create a unified workflow that delivers the best possible product for my clients.<br><br></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class="wp-block-column"><!-- wp:paragraph {"className":"animated fadeIn slow delay-500ms","style":{"typography":{"fontSize":"20px"}}} -->\n<p class="animated fadeIn slow delay-500ms" style="font-size:20px"><strong>Global Flexibility</strong></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow delay-500ms","style":{"typography":{"fontSize":"20px"}}} -->\n<p class="animated fadeIn slow delay-500ms" style="font-size:20px">While rooted in New York City, I’m comfortable traveling worldwide to set up and manage shoots wherever the client’s vision requires.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer {"height":"3em","width":"0px","style":{"layout":[]}} -->\n<div style="height:3em;width:0px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:cover {"url":"https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg","id":324,"alt":"Photo David Kausek holding camera on the beach in winter","hasParallax":true,"dimRatio":50,"overlayColor":"white","isUserOverlayColor":true,"focalPoint":{"x":0.85,"y":0.62},"minHeight":100,"minHeightUnit":"vh","contentPosition":"top center","isDark":false,"sizeSlug":"full","style":{"spacing":{"margin":{"bottom":"-24px"},"padding":{"right":"0px","left":"0px"}}},"layout":{"type":"default"}} -->\n<div class="wp-block-cover is-light has-parallax has-custom-content-position is-position-top-center" style="margin-bottom:-24px;padding-right:0px;padding-left:0px;min-height:100vh"><div role="img" aria-label="Photo David Kausek holding camera on the beach in winter" class="wp-block-cover__image-background wp-image-324 size-full has-parallax" style="background-position:85% 62%;background-image:url(https://davidkausek.com/wp-content/uploads/2026/05/david-camera-4.jpeg)"></div><span aria-hidden="true" class="wp-block-cover__background has-white-background-color has-background-dim"></span><div class="wp-block-cover__inner-container"><!-- wp:spacer {"height":"3em","width":"0px","metadata":{"blockVisibility":{"viewport":{"tablet":false,"mobile":false}}},"style":{"layout":[]}} -->\n<div style="height:3em;width:0px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:group {"layout":{"type":"constrained"}} -->\n<div class="wp-block-group"><!-- wp:heading {"level":3,"className":"animated fadeIn slow","style":{"typography":{"fontStyle":"normal","fontWeight":"600","textAlign":"left"}}} -->\n<h3 class="wp-block-heading has-text-align-left animated fadeIn slow" style="font-style:normal;font-weight:600">Let''s Connect</h3>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow","style":{"typography":{"lineHeight":1.6,"fontSize":"20px","textAlign":"left"}}} -->\n<p class="has-text-align-left animated fadeIn slow" style="font-size:20px;line-height:1.6">If you''re looking to bring your video or photography project to life, whether it is a live event, a corporate interview, or a global brand campaign, let’s connect and start a conversation.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {"className":"animated fadeIn formGroup slow","layout":{"type":"constrained","justifyContent":"center"}} -->\n<div class="wp-block-group animated fadeIn formGroup slow"><!-- wp:shortcode -->\n[formlayer id="2"]\n<!-- /wp:shortcode --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {"height":"3em","width":"0px","metadata":{"blockVisibility":{"viewport":{"tablet":false,"mobile":false}}},"style":{"layout":[]}} -->\n<div style="height:3em;width:0px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div></div>\n<!-- /wp:cover -->', 'About David', '', 'inherit', 'closed', 'closed', '', '372-revision-v1', '', '', '2026-07-27 16:45:14', '2026-07-27 20:45:14', '', 372, 'https://davidkausek.com/?p=1489', 0, 'revision', '', 0),
(1490, 1, '2026-07-27 16:50:23', '2026-07-27 20:50:23', '{\n    "custom_css[davidk-theme]": {\n        "value": "a.wp-block-navigation-item__content:hover { color: #ff3737 !important; }\\n:where(.wp-site-blocks) > * { margin-block-start: 0px; }\\n.formlayer-form { max-width: 700px; }\\n/*Form styles for dark bg*/\\n.formlayer-form label, \\n.formlayer-options-list .formlayer-option-label span, .lightForm .formlayer-section-break h3 { color: #fff !important; }\\n/* Form styles for light bg*/\\n.formGroup .formlayer-form label, .formGroup .formlayer-help-text,\\n.formGroup .formlayer-option-label span { color: #000 !important; }\\n/*General form styles*/\\n.formlayer-form label { font-weight: 400 !important; font-size: 1em !important; }\\n.formlayer-options-list .formlayer-option-label span { font-size: 1em !important; }\\n.formlayer-submit-btn { background: #32373c !important; font-weight: 400 !important; font-family: Urbanist; font-size: 1em !important; }\\n.formlayer-submit-btn:hover {background-color:orange !important;color:#000 !important;box-shadow:none !important;}\\ntextarea.formlayer-input  { font-family: arial; }\\n.formlayer-form-fields-wrapper .formlayer-section-break h3 {\\n\\tfont-size: 1.5em !important;\\n\\tfont-weight: normal !important;\\n}\\n/* Force Pagelayer Grid Gallery to stack on mobile */\\n@media (max-width: 768px) {\\n    .pagelayer-grid-gallery-ul {\\n        display:block !important;\\n    }\\n.pagelayer-gallery-item { padding: 16px 8px !important;}\\n}\\n/* Mobile specific*/\\n@media (max-width: 599px) {\\n/* Remove padding from mobile nav*/\\n\\t.wp-block-template-part .wp-block-group.is-layout-flow.wp-block-group-is-layout-flow {\\n\\tpadding-top: 0px !important;\\n\\tpadding-bottom: 0px !important;\\n }\\n\\t.wp-block-navigation__responsive-container-open svg, .wp-block-navigation-overlay-close svg {\\n\\twidth: 48px !important;\\n\\theight: 48px !important;\\n }\\n/* Keeps the desktop header menu text standard */\\n.wp-block-navigation:not(.is-menu-open) .wp-block-navigation-item {\\n    font-size: 16px; \\n}\\n\\n/* Forces the mobile overlay menu text to be larger */\\n.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation-item {\\n    font-size: 26px !important;\\n    line-height: 1.5;\\n}\\n/* Subheader mobile styles */\\n\\t.subpageHeader, #packages, .mobilePadding {\\n\\t\\tpadding-left: 7vw !important;\\n\\t\\tpadding-right: 7vw !important;\\n\\t}\\n\\t.subpageHeader p {\\n\\t\\tfont-size: 26px !important;\\n\\t\\tline-height: 43px !important;\\n\\t}\\n\\t#contactFormSection {\\n\\t\\tpadding-top: 0em !important;\\n    padding-bottom: 2em !important;\\n\\t}\\n\\t.myReelHeader h2 {\\n\\t\\tpadding-left: 11vw !important;\\n\\t}\\n}\\n/* Additional padding for Blog home right col*/\\n@media (min-width: 782px) {\\n.extraColPadding {\\n\\tpadding-left: 1.5em;\\n\\tpadding-right: 1em;\\n\\t}\\nh2.extraColPadding {\\n\\tpadding-left: .6em !important;\\n\\t}\\n}",\n        "type": "custom_css",\n        "user_id": 1,\n        "date_modified_gmt": "2026-07-27 20:50:23"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', '53b508f7-ba6e-4a3b-83c8-289c1b0943f5', '', '', '2026-07-27 16:50:23', '2026-07-27 20:50:23', '', 0, 'https://davidkausek.com/?p=1490', 0, 'customize_changeset', '', 0),
(1491, 1, '2026-07-27 16:50:23', '2026-07-27 20:50:23', 'a.wp-block-navigation-item__content:hover { color: #ff3737 !important; }\n:where(.wp-site-blocks) > * { margin-block-start: 0px; }\n.formlayer-form { max-width: 700px; }\n/*Form styles for dark bg*/\n.formlayer-form label, \n.formlayer-options-list .formlayer-option-label span, .lightForm .formlayer-section-break h3 { color: #fff !important; }\n/* Form styles for light bg*/\n.formGroup .formlayer-form label, .formGroup .formlayer-help-text,\n.formGroup .formlayer-option-label span { color: #000 !important; }\n/*General form styles*/\n.formlayer-form label { font-weight: 400 !important; font-size: 1em !important; }\n.formlayer-options-list .formlayer-option-label span { font-size: 1em !important; }\n.formlayer-submit-btn { background: #32373c !important; font-weight: 400 !important; font-family: Urbanist; font-size: 1em !important; }\n.formlayer-submit-btn:hover {background-color:orange !important;color:#000 !important;box-shadow:none !important;}\ntextarea.formlayer-input  { font-family: arial; }\n.formlayer-form-fields-wrapper .formlayer-section-break h3 {\n	font-size: 1.5em !important;\n	font-weight: normal !important;\n}\n/* Force Pagelayer Grid Gallery to stack on mobile */\n@media (max-width: 768px) {\n    .pagelayer-grid-gallery-ul {\n        display:block !important;\n    }\n.pagelayer-gallery-item { padding: 16px 8px !important;}\n}\n/* Mobile specific*/\n@media (max-width: 599px) {\n/* Remove padding from mobile nav*/\n	.wp-block-template-part .wp-block-group.is-layout-flow.wp-block-group-is-layout-flow {\n	padding-top: 0px !important;\n	padding-bottom: 0px !important;\n }\n	.wp-block-navigation__responsive-container-open svg, .wp-block-navigation-overlay-close svg {\n	width: 48px !important;\n	height: 48px !important;\n }\n/* Keeps the desktop header menu text standard */\n.wp-block-navigation:not(.is-menu-open) .wp-block-navigation-item {\n    font-size: 16px; \n}\n\n/* Forces the mobile overlay menu text to be larger */\n.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation-item {\n    font-size: 26px !important;\n    line-height: 1.5;\n}\n/* Subheader mobile styles */\n	.subpageHeader, #packages, .mobilePadding {\n		padding-left: 7vw !important;\n		padding-right: 7vw !important;\n	}\n	.subpageHeader p {\n		font-size: 26px !important;\n		line-height: 43px !important;\n	}\n	#contactFormSection {\n		padding-top: 0em !important;\n    padding-bottom: 2em !important;\n	}\n	.myReelHeader h2 {\n		padding-left: 11vw !important;\n	}\n}\n/* Additional padding for Blog home right col*/\n@media (min-width: 782px) {\n.extraColPadding {\n	padding-left: 1.5em;\n	padding-right: 1em;\n	}\nh2.extraColPadding {\n	padding-left: .6em !important;\n	}\n}', 'davidk-theme', '', 'inherit', 'closed', 'closed', '', '167-revision-v1', '', '', '2026-07-27 16:50:23', '2026-07-27 20:50:23', '', 167, 'https://davidkausek.com/?p=1491', 0, 'revision', '', 0);
