(1526, 1, '2026-07-27 18:11:21', '2026-07-27 22:11:21', '<!-- wp:cover {"url":"https://davidkausek.com/wp-content/uploads/2026/05/nature04-1024x768.jpg","id":211,"hasParallax":true,"dimRatio":80,"overlayColor":"custom-dark-gray","isUserOverlayColor":true,"minHeight":300,"contentPosition":"top left","sizeSlug":"large","className":"subpageHeader","style":{"spacing":{"padding":{"left":"4vw","top":"8vh","right":"4vw"}}},"layout":{"type":"constrained"}} -->\n<div class="wp-block-cover has-parallax has-custom-content-position is-position-top-left subpageHeader" style="padding-top:8vh;padding-right:4vw;padding-left:4vw;min-height:300px"><div class="wp-block-cover__image-background wp-image-211 size-large has-parallax" style="background-position:50% 50%;background-image:url(https://davidkausek.com/wp-content/uploads/2026/05/nature04-1024x768.jpg)"></div><span aria-hidden="true" class="wp-block-cover__background has-custom-dark-gray-background-color has-background-dim-80 has-background-dim"></span><div class="wp-block-cover__inner-container"><!-- wp:heading {"className":"animated fadeIn slow","style":{"elements":{"link":{"color":{"text":"var:preset|color|custom-link-red"}}}},"textColor":"custom-link-red"} -->\n<h2 class="wp-block-heading animated fadeIn slow has-custom-link-red-color has-text-color has-link-color">Photography</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow","style":{"elements":{"link":{"color":{"text":"var:preset|color|white"}}},"typography":{"fontSize":"1.3em"},"spacing":{"padding":{"top":"0.8em"}}},"textColor":"white"} -->\n<p class="animated fadeIn slow has-white-color has-text-color has-link-color" style="padding-top:0.8em;font-size:1.3em">See. Feel. Remember.</p>\n<!-- /wp:paragraph --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer {"height":"2.5em"} -->\n<div style="height:2.5em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {"className":"animated fadeIn","style":{"typ