(1699, 1, '2026-08-01 11:19:48', '2026-08-01 15:19:48', '<!-- wp:template-part {"slug":"header","theme":"davidk-theme","area":"header"} /-->\n\n<!-- wp:cover {"url":"https://davidkausek.com/wp-content/uploads/2026/05/IMG_6307-1024x768.jpeg","id":83,"alt":"a view of the sunset","hasParallax":true,"dimRatio":60,"customOverlayColor":"#000000","isUserOverlayColor":true,"minHeight":100,"minHeightUnit":"vh","contentPosition":"center center","sizeSlug":"large","metadata":{"categories":["banner"],"patternName":"core/large-header-with-text-and-a-button","name":"Large header with text and a button"},"align":"full","className":"animated fadeIn ","style":{"spacing":{"padding":{"right":"2em","left":"2em"}}},"layout":{"type":"default"}} -->\n<div class="wp-block-cover alignfull has-parallax animated fadeIn" style="padding-right:2em;padding-left:2em;min-height:100vh"><div role="img" aria-label="a view of the sunset" class="wp-block-cover__image-background wp-image-83 size-large has-parallax" style="background-position:50% 50%;background-image:url(https://davidkausek.com/wp-content/uploads/2026/05/IMG_6307-1024x768.jpeg)"></div><span aria-hidden="true" class="wp-block-cover__background has-background-dim-60 has-background-dim" style="background-color:#000000"></span><div class="wp-block-cover__inner-container"><!-- wp:heading {"className":"alignwide has-white-color has-text-color","style":{"typography":{"fontSize":"48px","lineHeight":"1.2","fontStyle":"normal","fontWeight":"500"}}} -->\n<h2 class="wp-block-heading alignwide has-white-color has-text-color" style="font-size:48px;font-style:normal;font-weight:500;line-height:1.2"><strong>David Kausek</strong> | Livestream Specialist, Videographer and Photographer</h2>\n<!-- /wp:heading -->\n\n<!-- wp:site-tagline /-->\n\n<!-- wp:columns {"align":"wide"} -->\n<div class="wp-block-columns alignwide"><!-- wp:column {"width":"60%"} -->\n<div class="wp-block-column" style="flex-basis:60%"><!-- wp:paragraph {"style":{"color":{"text":"#ffffff"}}} -->\n<p class="has-text-color" style="color:#ffffff"></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {"style":{"typography":{"fontSize":"1.2em"}}} -->\n<div class="wp-block-buttons has-custom-font-size" style="font-size:1.2em"><!-- wp:button {"className":"is-style-outline animated fadeIn slow","style":{"color":{"text":"#ffffff","background":"#000000"}}} -->\n<div class="wp-block-button is-style-outline animated fadeIn slow"><a class="wp-block-button__link has-text-color has-background wp-element-button" href="#myReel" style="color:#ffffff;background-color:#000000">View my reel</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {"className":"is-style-outline animated fadeIn slow delay-200ms","style":{"color":{"text":"#ffffff","background":"#000000"}}} -->\n<div class="wp-block-button is-style-outline animated fadeIn slow delay-200ms"><a class="wp-block-button__link has-text-color has-background wp-element-button" href="https://davidkausek.com/photography" style="color:#ffffff;background-color:#000000">View my photography</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class="wp-block-column"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {"className":"animated fadeIn slow","anchor":"myReel"} -->\n<div class="wp-block-columns animated fadeIn slow" id="myReel"><!-- wp:column {"className":"myReelHeader","layout":{"type":"constrained"}} -->\n<div class="wp-block-column myReelHeader"><!-- wp:heading -->\n<h2 class="wp-block-heading">View my reel</h2>\n<!-- /wp:heading -->\n\n<!-- wp:video -->\n<figure class="wp-block-video"><video controls poster="https://davidkausek.com/wp-content/uploads/2026/05/2016_david_kausek_reel.mp4.Still001.png" preload="none" src="https://www.davidkausek.com/video/2016_david_kausek_reel.mp4"></video></figure>\n<!-- /wp:video --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:spacer -->\n<div style="height:100px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns -->\n<div class="wp-block-columns"><!-- wp:column {"style":{"color":{"background":"#1a1a1a"}}} -->\n<div class="wp-block-column has-background" style="background-color:#1a1a1a"><!-- wp:columns {"metadata":{"categories":["text"],"name":"Image on solid color with description"},"align":"full"} -->\n<div class="wp-block-columns alignfull"><!-- wp:column {"width":"50%","className":"animated fadeIn slow"} -->\n<div class="wp-block-column animated fadeIn slow" style="flex-basis:50%"><!-- wp:cover {"customOverlayColor":"#f6f6f6","isUserOverlayColor":true,"minHeight":600,"className":"is-light"} -->\n<div class="wp-block-cover is-light" style="min-height:600px"><span aria-hidden="true" class="wp-block-cover__background has-background-dim-100 has-background-dim" style="background-color:#f6f6f6"></span><div class="wp-block-cover__inner-container"><!-- wp:image {"id":45,"sizeSlug":"medium","linkDestination":"none","align":"center"} -->\n<figure class="wp-block-image aligncenter size-medium"><img src="https://davidkausek.com/wp-content/uploads/2026/05/davidk-320x320-1-300x300.jpg" alt="Photo of David Kausek" class="wp-image-45"/></figure>\n<!-- /wp:image --></div></div>\n<!-- /wp:cover --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"verticalAlignment":"center","style":{"spacing":{"padding":{"top":"1em","right":"1em","bottom":"1em","left":"1em"}}}} -->\n<div class="wp-block-column is-vertically-aligned-center" style="padding-top:1em;padding-right:1em;padding-bottom:1em;padding-left:1em"><!-- wp:columns -->\n<div class="wp-block-columns"><!-- wp:column {"verticalAlignment":"center","width":"320px","style":{"spacing":{"padding":{"left":"24px"}}}} -->\n<div class="wp-block-column is-vertically-aligned-center" style="padding-left:24px;flex-basis:320px"><!-- wp:spacer {"height":"2em","metadata":{"blockVisibility":{"viewport":{"desktop":false,"tablet":false}}}} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow","style":{"typography":{"lineHeight":"1.6","fontStyle":"italic","fontWeight":"800","fontSize":"1.4em"}},"fontFamily":"urbanist"} -->\n<p class="animated fadeIn slow has-urbanist-font-family" style="font-size:1.4em;font-style:italic;font-weight:800;line-height:1.6">List of Skills</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:list {"style":{"typography":{"lineHeight":1.6}}} -->\n<ul style="line-height:1.6" class="wp-block-list"><!-- wp:list-item {"className":"animated fadeIn slow","fontSize":"medium"} -->\n<li class="animated fadeIn slow has-medium-font-size">Livestream Technical Director</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"className":"animated fadeIn slow","fontSize":"medium"} -->\n<li class="animated fadeIn slow has-medium-font-size">Videographer / Director of Photography</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"className":"animated fadeIn slow","fontSize":"medium"} -->\n<li class="animated fadeIn slow has-medium-font-size">Camera Operator</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"className":"animated fadeIn slow","fontSize":"medium"} -->\n<li class="animated fadeIn slow has-medium-font-size">Video Editor</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"className":"animated fadeIn slow","fontSize":"medium"} -->\n<li class="animated fadeIn slow has-medium-font-size">Portrait Photography</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"className":"animated fadeIn slow","fontSize":"medium"} -->\n<li class="animated fadeIn slow has-medium-font-size">Event Photography</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:spacer {"height":"0.5em"} -->\n<div style="height:0.5em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {"className":"mobileCenter","style":{"typography":{"fontSize":"1.2em"}},"layout":{"type":"flex","justifyContent":"left"}} -->\n<div class="wp-block-buttons has-custom-font-size mobileCenter" style="font-size:1.2em"><!-- wp:button {"className":"animated fadeIn ","style":{"border":{"width":"2px"}},"borderColor":"white"} -->\n<div class="wp-block-button animated fadeIn"><a class="wp-block-button__link has-border-color has-white-border-color wp-element-button" href="https://davidkausek.com/about/" style="border-width:2px">Learn about David</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:spacer {"height":"3em","metadata":{"blockVisibility":{"viewport":{"desktop":false,"tablet":false}}}} -->\n<div style="height:3em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:cover {"overlayColor":"custom-dark-gray","isUserOverlayColor":true,"minHeight":340,"contentPosition":"center center","sizeSlug":"large","style":{"spacing":{"margin":{"top":"0px"}}},"layout":{"type":"constrained","contentSize":"1000px"}} -->\n<div class="wp-block-cover" style="margin-top:0px;min-height:340px"><span aria-hidden="true" class="wp-block-cover__background has-custom-dark-gray-background-color has-background-dim-100 has-background-dim"></span><div class="wp-block-cover__inner-container"><!-- wp:spacer {"height":"3em","metadata":{"blockVisibility":{"viewport":{"desktop":false,"tablet":false}}}} -->\n<div style="height:3em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {"level":3,"className":"animated fadeIn slow","style":{"typography":{"textAlign":"center","fontSize":"1.8em"}},"fontFamily":"system-font"} -->\n<h3 class="wp-block-heading has-text-align-center animated fadeIn slow has-system-font-font-family" style="font-size:1.8em">Need photos for headshots, events, or fine art?  INSERT INTO `wpk3_posts` VALUES
(1708, 1, '2026-08-01 11:30:00', '2026-08-01 15:30:00', '{\n    "custom_css[davidk-theme]": {\n        "value": "a.wp-block-navigation-item__content:hover { color: #ff3737 !important; }\\n:where(.wp-site-blocks) > * { margin-block-start: 0px; }\\n.formlayer-form { max-width: 700px; }\\n/*Form styles for dark bg*/\\n.formlayer-form label, \\n.formlayer-options-list .formlayer-option-label span, .lightForm .formlayer-section-break h3 { color: #fff !important; }\\n/* Form styles for light bg*/\\n.formGroup .formlayer-form label, .formGroup .formlayer-help-text,\\n.formGroup .formlayer-option-label span { color: #000 !important; }\\n/*General form styles*/\\n.formlayer-form label { font-weight: 400 !important; font-size: 18px !important; }\\n.formlayer-form input[type=\\"text\\"],\\n.formlayer-form input[type=\\"email\\"],\\n.formlayer-form input[type=\\"number\\"], \\n.formlayer-form input[type=\\"tel\\"], \\n.formlayer-form input[type=\\"date\\"], \\n.formlayer-form input[type=\\"password\\"], \\n.formlayer-form input[type=\\"url\\"],\\n.formlayer-form textarea, .formlayer-form select { font-size: 17px !important; font-family: arial;}\\n.formlayer-options-list .formlayer-option-label span { font-size: 18px !important; }\\n.formlayer-help-text { font-size: 17px !important; }\\n.formlayer-submit-btn { background: #32373c !important; font-weight: 400 !important; font-family: Urbanist; font-size: 1em !important; box-shadow:none !important; }\\n.formlayer-submit-btn:hover {background-color:orange !important;color:#000 !important;box-shadow:none !important;}\\ntextarea.formlayer-input  { font-family: arial; }\\n.formlayer-form-fields-wrapper .formlayer-section-break h3 {\\n\\tfont-size: 1.5em !important;\\n\\tfont-weight: normal !important;\\n}\\n/* Force Pagelayer Grid Gallery to stack on mobile */\\n@media (max-width: 768px) {\\n    .pagelayer-grid-gallery-ul {\\n        display:block !important;\\n    }\\n.pagelayer-gallery-item { padding: 16px 8px !important;}\\n}\\n/* Mobile specific*/\\n@media (max-width: 599px) {\\n/* Remove padding from mobile nav*/\\n\\t.wp-block-template-part .wp-block-group.is-layout-flow.wp-block-group-is-layout-flow {\\n\\tpadding-top: 0px !important;\\n\\tpadding-bottom: 0px !important;\\n }\\n\\t.wp-block-navigation__responsive-container-open svg, .wp-block-navigation-overlay-close svg {\\n\\twidth: 48px !important;\\n\\theight: 48px !important;\\n }\\n/* Keeps the desktop header menu text standard */\\n.wp-block-navigation:not(.is-menu-open) .wp-block-navigation-item {\\n    font-size: 16px; \\n}\\n\\n/* Forces the mobile overlay menu text to be larger */\\n.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation-item {\\n    font-size: 26px !important;\\n    line-height: 1.5;\\n}\\n/* Subheader mobile styles */\\n\\t.subpageHeader, #packages, .mobilePadding {\\n\\t\\tpadding-left: 7vw !important;\\n\\t\\tpadding-right: 7vw !important;\\n\\t}\\n\\t.subpageHeader p {\\n\\t\\tfont-size: 26px !important;\\n\\t\\tline-height: 43px !important;\\n\\t}\\n\\t#contactFormSection {\\n\\t\\tpadding-top: 0em !important;\\n    padding-bottom: 2em !important;\\n\\t}\\n\\t.myReelHeader h2 {\\n\\t\\tpadding-left: 11vw !important;\\n\\t}\\n/* Adjustments for pricing cards*/\\n\\t.pricing-cards-container {\\n\\t\\tpadding-top: 1em !important;\\n\\t\\tpadding-bottom: 0em !important;\\n\\t}\\n\\t.pricing-cards-container .pricing-cards-list ul.wp-block-list {\\n\\t\\tmax-width: 90% !important;\\n\\t}\\n}\\n/* Additional padding for Blog home right col*/\\n@media (min-width: 782px) {\\n.extraColPadding {\\n\\tpadding-left: 1.5em;\\n\\tpadding-right: 1em;\\n\\t}\\nh2.extraColPadding {\\n\\tpadding-left: .6em !important;\\n\\t}\\n}\\n/* Fix iOS Safari font-size adjustment in overlays */\\n/* Prevent iOS text inflation inside Fancybox modals */\\n/* 1. Stop iOS Safari text-inflation specifically inside FancyBox v2 */\\n.fancybox-wrap,\\n.fancybox-skin,\\n.fancybox-outer,\\n.fancybox-inner {\\n    -webkit-text-size-adjust: 100% !important;\\n    text-size-adjust: 100% !important;\\n}\\n\\n/* 2. Lock text inside the modal to your desired font scale on mobile viewports */\\n@media screen and (max-width: 767px) {\\n    /* Targets every text element strictly within the v2 inner content window */\\n    .fancybox-inner,\\n    .fancybox-inner p,\\n    .fancybox-inner span,\\n    .fancybox-inner li,\\n    .fancybox-inner div {\\n        font-size: 20px !important; /* Force your exact base layout text size */\\n        line-height: 1.5 !important;\\n    }\\n    .fancybox-inner h1, .fancybox-inner h2 {\\n        font-size: 32px !important; \\n    }\\n    .fancybox-inner h3, .fancybox-inner h4 {\\n        font-size: 28px !important; \\n    }\\n}\\n\\n@media screen and (max-width: 781px) {\\n\\t\\t/*Center text on Mobile and tablet*/\\n\\t.mobileCenter {\\n\\t\\tjustify-content: center !important;\\n\\t}\\n\\t.home mobileCenter {\\n\\t\\tmargin-left: 24px !important;\\n\\t}\\n}",\n        "type": "custom_css",\n        "user_id": 1,\n        "date_modified_gmt": "2026-08-01 15:30:00"\n    }\n}', '', '', 'trash', 'closed', 'closed', '', 'f74042ed-1973-481a-97ea-9a4ba3883517', '', '', '2026-08-01 11:30:00', '2026-08-01 15:30:00', '', 0, 'https://davidkausek.com/2026/08/01/f74042ed-1973-481a-97ea-9a4ba3883517/', 0, 'customize_changeset', '', 0),
