(1712, 1, '2026-08-01 11:52:43', '2026-08-01 15:52:43', '<!-- wp:template-part {"slug":"header","theme":"davidk-theme","area":"header"} /-->\n\n<!-- wp:cover {"url":"https://davidkausek.com/wp-content/uploads/2026/05/IMG_6307-1024x768.jpeg","id":83,"alt":"a view of the sunset","hasParallax":true,"dimRatio":60,"customOverlayColor":"#000000","isUserOverlayColor":true,"minHeight":100,"minHeightUnit":"vh","contentPosition":"center center","sizeSlug":"large","metadata":{"categories":["banner"],"patternName":"core/large-header-with-text-and-a-button","name":"Large header with text and a button"},"align":"full","className":"animated fadeIn ","style":{"spacing":{"padding":{"right":"2em","left":"2em"}}},"layout":{"type":"default"}} -->\n<div class="wp-block-cover alignfull has-parallax animated fadeIn" style="padding-right:2em;padding-left:2em;min-height:100vh"><div role="img" aria-label="a view of the sunset" class="wp-block-cover__image-background wp-image-83 size-large has-parallax" style="background-position:50% 50%;background-image:url(https://davidkausek.com/wp-content/uploads/2026/05/IMG_6307-1024x768.jpeg)"></div><span aria-hidden="true" class="wp-block-cover__background has-background-dim-60 has-background-dim" style="background-color:#000000"></span><div class="wp-block-cover__inner-container"><!-- wp:heading {"className":"alignwide has-white-color has-text-color","style":{"typography":{"fontSize":"48px","lineHeight":"1.2","fontStyle":"normal","fontWeight":"500"}}} -->\n<h2 class="wp-block-heading alignwide has-white-color has-text-color" style="font-size:48px;font-style:normal;font-weight:500;line-height:1.2"><strong>David Kausek</strong> | Livestream Specialist, Videographer and Photographer</h2>\n<!-- /wp:heading -->\n\n<!-- wp:site-tagline /-->\n\n<!-- wp:columns {"align":"wide"} -->\n<div class="wp-block-columns alignwide"><!-- wp:column {"width":"60%"} -->\n<div class="wp-block-column" style="flex-basis:60%"><!-- wp:paragraph {"style":{"color":{"text":"#ffffff"}}} -->\n<p class="has-text-color" style="color:#ffffff"></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:buttons {"style":{"typography":{"fontSize":"1.2em"}}} -->\n<div class="wp-block-buttons has-custom-font-size" style="font-size:1.2em"><!-- wp:button {"className":"is-style-outline animated fadeIn slow","style":{"color":{"text":"#ffffff","background":"#000000"}}} -->\n<div class="wp-block-button is-style-outline animated fadeIn slow"><a class="wp-block-button__link has-text-color has-background wp-element-button" href="#myReel" style="color:#ffffff;background-color:#000000">View my reel</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {"className":"is-style-outline animated fadeIn slow delay-200ms","style":{"color":{"text":"#ffffff","background":"#000000"}}} -->\n<div class="wp-block-button is-style-outline animated fadeIn slow delay-200ms"><a class="wp-block-button__link has-text-color has-background wp-element-button" href="https://davidkausek.com/photography" style="color:#ffffff;background-color:#000000">View my photography</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column -->\n\n<!-- wp:column -->\n<div class="wp-block-column"></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:columns {"className":"animated fadeIn slow","anchor":"myReel"} -->\n<div class="wp-block-columns animated fadeIn slow" id="myReel"><!-- wp:column {"className":"myReelHeader","layout":{"type":"constrained"}} -->\n<div class="wp-block-column myReelHeader"><!-- wp:heading -->\n<h2 class="wp-block-heading">View my reel</h2>\n<!-- /wp:heading -->\n\n<!-- wp:video -->\n<figure class="wp-block-video"><video controls poster="https://davidkausek.com/wp-content/uploads/2026/05/2016_david_kausek_reel.mp4.Still001.png" preload="none" src="https://www.davidkausek.com/video/2016_david_kausek_ree