(1724, 1, '2026-08-01 12:53:37', '2026-08-01 16:53:37', '<!-- wp:group {"layout":{"inherit":true,"type":"constrained"}} -->\n<div class="wp-block-group"><!-- wp:group {"style":{"spacing":{"padding":{"top":"0px","bottom":"1em"}}}} -->\n<div class="wp-block-group" style="padding-top:0px;padding-bottom:1em"><!-- wp:spacer -->\n<div style="height:100px" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {"style":{"typography":{"textAlign":"center"},"elements":{"link":{"color":{"text":"var:preset|color|white"}}}},"textColor":"white","fontSize":"medium"} -->\n<p class="has-text-align-center has-white-color has-text-color has-link-color has-medium-font-size">© 2026 David Kausek · <a href="https://davidkausek.com/contact-me/" data-type="page" data-id="60">Contact</a> · Website by <a href="https://sheryl.kausek.com/" data-type="link" data-id="https://sheryl.kausek.com/" target="_blank" rel="noreferrer noopener">SK web solutions</a></p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:group -->', 'footer', '', 'inherit', 'closed', 'closed', '', '85-revision-v1', '', '', '2026-08-01 12:53:37', '2026-08-01 16:53:37', '', 85, 'https://davidkausek.com/?p=1724', 0, 'revision', '', 0),
