"style":{"typography":{"textAlign":"center","fontStyle":"normal","fontWeight":"200","fontSize":"22px","letterSpacing":"1px"}},"fontFamily":"urbanist"} -->\n<p class="has-text-align-center has-urbanist-font-family" style="font-size:22px;font-style:normal;font-weight:200;letter-spacing:1px">15 edited photos</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {"className":"pricing-cards-list","layout":{"type":"constrained","contentSize":"70%"}} -->\n<div class="wp-block-group pricing-cards-list"><!-- wp:list {"style":{"spacing":{"margin":{"top":"24px"}}}} -->\n<ul style="margin-top:24px" class="wp-block-list"><!-- wp:list-item {"style":{"spacing":{"padding":{"bottom":"1em"}}}} -->\n<li style="padding-bottom:1em">Light retouching and polish</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"style":{"spacing":{"padding":{"bottom":"1em"}}}} -->\n<li style="padding-bottom:1em"><strong>Individual:</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>starting at $650</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Groups (per person):</strong>&nbsp;<!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item {"style":{"spacing":{"padding":{"bottom":"0.5em"}}}} -->\n<li style="padding-bottom:0.5em">2 people $595</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"style":{"spacing":{"padding":{"bottom":"0.5em"}}}} -->\n<li style="padding-bottom:0.5em">5 people $565</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>10 people $535</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:column -->\n\n<!-- wp:column {"className":"pricing-cards-container","style":{"spacing":{"padding":{"top":"2em","bottom":"2em"}},"border":{"radius":{"topLeft":"14px","topRight":"14px","bottomLeft":"14px","bottomRight":"14px"}}},"backgroundColor":"custom-dark-gray"} -->\n<div class="wp-block-column pricing-cards-container has-custom-dark-gray-background-color has-background" style="border-top-left-radius:14px;border-top-right-radius:14px;border-bottom-left-radius:14px;border-bottom-right-radius:14px;padding-top:2em;padding-bottom:2em"><!-- wp:spacer {"height":"2.5em","metadata":{"blockVisibility":{"viewport":{"mobile":false}}}} -->\n<div style="height:2.5em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {"level":4,"style":{"typography":{"textAlign":"center","fontStyle":"normal","fontWeight":"500","fontSize":"28px"},"spacing":{"margin":{"bottom":"-12px"}}}} -->\n<h4 class="wp-block-heading has-text-align-center" style="margin-bottom:-12px;font-size:28px;font-style:normal;font-weight:500">Premium</h4>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"style":{"typography":{"textAlign":"center","fontStyle":"normal","fontWeight":"200","fontSize":"22px","letterSpacing":"1px"}},"fontFamily":"urbanist"} -->\n<p class="has-text-align-center has-urbanist-font-family" style="font-size:22px;font-style:normal;font-weight:200;letter-spacing:1px">30 edited photos</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:group {"className":"pricing-cards-list","layout":{"type":"constrained","contentSize":"70%"}} -->\n<div class="wp-block-group pricing-cards-list"><!-- wp:list {"style":{"typography":{"fontSize":"21px"},"spacing":{"margin":{"top":"24px"}}}} -->\n<ul style="margin-top:24px;font-size:21px" class="wp-block-list"><!-- wp:list-item {"style":{"spacing":{"padding":{"bottom":"1em"}}}} -->\n<li style="padding-bottom:1em">Enhanced retouching and 3-5 business days priority turnaround</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"style":{"spacing":{"padding":{"bottom":"1em"}}}} -->\n<li style="padding-bottom:1em"><strong>Individual:</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item -->\n<li>starting&nbsp;at $1,300</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><strong>Groups (per person):</strong><!-- wp:list -->\n<ul class="wp-block-list"><!-- wp:list-item {"style":{"spacing":{"padding":{"bottom":"0.5em"}}}} -->\n<li style="padding-bottom:0.5em">2 people $1,190</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"style":{"spacing":{"padding":{"bottom":"0.5em"}}}} -->\n<li style="padding-bottom:0.5em">5 people $1,090</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li>10 people $1,025</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></div>\n<!-- /wp:group -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->\n\n<!-- wp:columns {"style":{"spacing":{"padding":{"bottom":"2em","top":"0em"}}}} -->\n<div class="wp-block-columns" style="padding-top:0em;padding-bottom:2em"><!-- wp:column -->\n<div class="wp-block-column"><!-- wp:group {"style":{"spacing":{"blockGap":"0"}},"layout":{"type":"constrained","contentSize":"1150px"}} -->\n<div class="wp-block-group"><!-- wp:spacer {"height":"1em","metadata":{"blockVisibility":{"viewport":{"tablet":false,"mobile":false}}}} -->\n<div style="height:1em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:paragraph {"style":{"spacing":{"padding":{"right":"0vw","left":"0vw"}},"elements":{"link":{"color":{"text":"var:preset|color|custom-grey-blue"}}},"typography":{"textAlign":"center","fontSize":"22px"}},"textColor":"custom-grey-blue"} -->\n<p class="has-text-align-center has-custom-grey-blue-color has-text-color has-link-color" style="padding-right:0vw;padding-left:0vw;font-size:22px"><strong>Note:</strong> Final rates depend on number of people, needed looks/backgrounds, and whether editing volume per person stays at the tiered allowance.</p>\n<!-- /wp:paragraph --></div>\n<!-- /wp:group --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns -->', 'Pricing Cards', '', 'inherit', 'closed', 'closed', '', '1626-revision-v1', '', '', '2026-08-02 15:31:07', '2026-08-02 19:31:07', '', 1626, 'https://davidkausek.com/?p=1745', 0, 'revision', '', 0);
INSERT INTO `wpk3_snippets` VALUES
(1, 'Make upload filenames lowercase', 'Makes sure that image and file uploads have lowercase filenames.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_filter( ''sanitize_file_name'', ''mb_strtolower'' );', 'sample, media', 'global', 0, 10, 0, '2026-07-24 13:33:30', 1, NULL),
(2, 'Disable admin bar', 'Turns off the WordPress admin bar for everyone except administrators.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_action( ''wp'', function () {\n	if ( ! current_user_can( ''manage_options'' ) ) {\n		show_admin_bar( false );\n	}\n} );', 'sample, admin-bar', 'front-end', 0, 10, 0, '2026-07-24 13:33:30', 1, NULL),
(3, 'Allow smilies', 'Allows smiley conversion in obscure places.\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', 'add_filter( ''widget_text'', ''convert_smilies'' );\nadd_filter( ''the_title'', ''convert_smilies'' );\nadd_filter( ''wp_title'', ''convert_smilies'' );\nadd_filter( ''get_bloginfo'', ''convert_smilies'' );', 'sample', 'global', 0, 10, 0, '2026-07-24 13:33:30', 1, NULL),
(4, 'Current year', 'Shortcode for inserting the current year into a post or page..\n\nThis is a sample snippet. Feel free to use it, edit it, or remove it.', '<?php echo date( ''Y'' ); ?>', 'sample, dates', 'content', 0, 10, 0, '2026-07-24 13:33:30', 1, NULL),
(5, 'Line breaks for excerpts', '', 'function keep_line_breaks_in_auto_excerpt( $text ) {\n    global $post;\n    \n    // Ensure we have a valid post object before running\n    if ( ! isset( $post->ID ) ) {\n        return $text;\n    }\n    \n    // Only target auto-generated excerpts\n    if ( '''' === $post->post_excerpt ) {\n        // Fix for sticky posts: Safely fetch the content by ID directly\n        $content = get_post_field( ''post_content'', $post->ID );\n        $content = strip_shortcodes( $content );\n        \n        // Safety Check 1: Delete specific common Lorem Ipsum demo strings\n        if ( strpos( $content, ''Lorem Ipsum has been the industry'' ) !== false ) {\n            return '''';\n        }\n        \n        // Safety Check 2: If there is no raw content, stop immediately\n        if ( empty( trim( strip_tags( $content ) ) ) ) {\n            return '''';\n        }\n        \n        // Replace block endings and clean up tags while keeping structural spacing\n        $text = str_replace( array(''</p>'', ''<br />'', ''<br>''), "\\n", $content );\n        $text = strip_tags( $text );\n        \n        // Define your desired word limit\n        $excerpt_length = apply_filters( ''excerpt_length'', 55 );\n        $words = explode( '' '', $text, $excerpt_length + 1 );\n        \n        if ( count( $words ) > $excerpt_length ) {\n            array_pop( $words );\n            $text = implode( '' '', $words );\n            $text = $text . ''...'';\n        }\n        \n        // Re-apply paragraph and line break formatting\n        $text = wpautop( $text );\n    }\n    return $text;\n}\nremove_filter( ''get_the_excerpt'', ''wp_trim_excerpt'' );\nadd_filter( ''get_the_excerpt'', ''keep_line_breaks_in_auto_excerpt'' );', 'excerpt', 'global', 0, 10, 1, '2026-07-24 14:05:35', 1, NULL),
(6, 'Hide Elementor', '', '/**\n * Custom Block Theme Fix: Scrub leftovers and force-inject front-end editor builders\n */\n\n// 1. Force kill the ghost Elementor sidebar menu item\nadd_action( ''admin_menu'', ''custom_theme_scrub_elementor_leftovers'', 999 );\nfunction custom_theme_scrub_elementor_leftovers() {\n    remove_menu_page( ''elementor'' ); // Deletes primary ghost menu\n    remove_menu_page( ''edit.php?post_type=elementor_library'' ); // Deletes leftover templates menu\n}\n\n// 2. Force block theme templates to load Pagelayer live front-end bar script hooks\nadd_action( ''wp_enqueue_scripts'', ''custom_theme_force_pagelayer_assets'', 100 );\nfunction custom_theme_force_pagelayer_assets() {\n    if ( is_user_logged_in() && class_exists( ''pagelayer'' ) ) {\n        // Forces WordPress block theme to recognize the asset queue for the live editor icon\n        wp_enqueue_script( ''pagelayer-admin-bar'' );\n        wp_enqueue_style( ''pagelayer-admin-bar'' );\n    }\n}\n', 'remove section, elementor', 'global', 0, 10, 1, '2026-08-01 14:09:05', 1, NULL);
