wp:list-item -->\n\n<!-- wp:list-item {"className":"animated fadeIn slow"} -->\n<li class="animated fadeIn slow">Pre‑planning consultation&nbsp;&nbsp;</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"className":"animated fadeIn slow"} -->\n<li class="animated fadeIn slow">Digital gallery + high‑res images &amp; prints</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:spacer {"height":"1.5em"} -->\n<div style="height:1.5em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {"className":"animated fadeIn slow","layout":{"type":"flex","justifyContent":"center"}} -->\n<div class="wp-block-buttons animated fadeIn slow"><!-- wp:button {"style":{"typography":{"fontSize":"1.2em"}}} -->\n<div class="wp-block-button"><a class="wp-block-button__link has-custom-font-size wp-element-button" href="#form" style="font-size:1.2em">Reserve your date</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons --></div>\n<!-- /wp:column --></div>\n<!-- /wp:columns --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {"className":"fancybox-hidden","layout":{"type":"constrained"},"anchor":"uniqueID"} -->\n<div id="uniqueID" class="wp-block-group fancybox-hidden"><!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {"level":3} -->\n<h3 class="wp-block-heading">Pricing for Professional Headshots</h3>\n<!-- /wp:heading -->\n\n<!-- wp:table -->\n<figure class="wp-block-table"><table class="has-fixed-layout"><thead><tr><th>Tier</th><th>Individual start</th><th>2 people (per person)</th><th>5 people (per person)</th><th>10 people (per person)</th></tr></thead><tbody><tr><td>Essential (10 edited)</td><td>$425</td><td>$395</td><td>$365</td><td>$345</td></tr><tr><td>Standard (15 edited)</td><td>$575</td><td>$525</td><td>$495</td><td>$470</td></tr><tr><td>Premium (30 edited)</td><td>$1,300</td><td>$1,190</td><td>$1,090</td><td>$1,025</td></tr></tbody></table></figure>\n<!-- /wp:table -->\n\n<!-- wp:paragraph {"style":{"typography":{"fontSize":"17px"},"elements":{"link":{"color":{"text":"var:preset|color|custom-grey-blue"}}}},"textColor":"custom-grey-blue"} -->\n<p class="has-custom-grey-blue-color has-text-color has-link-color" style="font-size:17px"><strong>Note:</strong> Final rates depend on number of people, needed looks/backgrounds, and whether editing volume per person stays at the tiered allowance.</p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {"height":"3em"} -->\n<div style="height:3em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div>\n<!-- /wp:group -->\n\n<!-- wp:group {"style":{"spacing":{"margin":{"top":"-0.5px"}}},"backgroundColor":"custom-dark-gray","layout":{"type":"constrained","justifyContent":"center","contentSize":"1200px"}} -->\n<div class="wp-block-group has-custom-dark-gray-background-color has-background" style="margin-top:-0.5px"><!-- wp:columns {"className":"animated fadeIn slow","style":{"spacing":{"padding":{"top":"4em","bottom":"4em","left":"0px","right":"0px"},"blockGap":{"top":"0px","left":"4em"},"margin":{"top":"0em"}}},"backgroundColor":"custom-dark-gray"} -->\n<div class="wp-block-columns animated fadeIn slow has-custom-dark-gray-background-color has-background" style="margin-top:0em;padding-top:4em;padding-right:0px;padding-bottom:4em;padding-left:0px"><!-- wp:column {"verticalAlignment":"stretch","style":{"spacing":{"padding":{"left":"1em","bottom":"2em"}}},"layout":{"type":"constrained","justifyContent":"right"}} -->\n<div class="wp-block-column is-vertically-aligned-stretch" style="padding-bottom:2em;padding-left:1em"><!-- wp:heading {"level":3,"className":"animated fadeIn slow"} -->\n<h3 class="wp-block-heading animated fadeIn slow">Event Coverage</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {"style":{"typography":{"lineHeight":"1.7","fontSize":"1.3em"}}} -->\n<ul style="font-size:1.3em;line-height:1.7" class="wp-block-list"><!-- wp:list-item {"className