up.is-layout-flow.wp-block-group-is-layout-flow {\n	padding-top: 0px !important;\n	padding-bottom: 0px !important;\n }\n	.wp-block-navigation__responsive-container-open svg, .wp-block-navigation-overlay-close svg {\n	width: 48px !important;\n	height: 48px !important;\n }\n/* Keeps the desktop header menu text standard */\n.wp-block-navigation:not(.is-menu-open) .wp-block-navigation-item {\n    font-size: 16px; \n}\n\n/* Forces the mobile overlay menu text to be larger */\n.wp-block-navigation__responsive-container.is-menu-open .wp-block-navigation-item {\n    font-size: 26px !important;\n    line-height: 1.5;\n}\n/* Subheader mobile styles */\n	.subpageHeader, #packages, .mobilePadding {\n		padding-left: 7vw !important;\n		padding-right: 7vw !important;\n	}\n	.subpageHeader p {\n		font-size: 26px !important;\n		line-height: 43px !important;\n	}\n	#contactFormSection {\n		padding-top: 0em !important;\n    padding-bottom: 2em !important;\n	}\n	.myReelHeader h2 {\n		padding-left: 11vw !important;\n	}\n}\n/* Additional padding for Blog home right col*/\n@media (min-width: 782px) {\n.extraColPadding {\n	padding-left: 1.5em;\n	padding-right: 1em;\n	}\nh2.extraColPadding {\n	padding-left: .6em !important;\n	}\n}\n/* Fix iOS Safari font-size adjustment in overlays */\n/* Prevent iOS text inflation inside Fancybox modals */\n/* 1. Stop iOS Safari text-inflation specifically inside FancyBox v2 */\n.fancybox-wrap,\n.fancybox-skin,\n.fancybox-outer,\n.fancybox-inner {\n    -webkit-text-size-adjust: 100% !important;\n    text-size-adjust: 100% !important;\n}\n\n/* 2. Lock text inside the modal to your desired font scale on mobile viewports */\n@media screen and (max-width: 767px) {\n    /* Targets every text element strictly within the v2 inner content window */\n    .fancybox-inner,\n    .fancybox-inner p,\n    .fancybox-inner span,\n    .fancybox-inner li,\n    .fancybox-inner div {\n        font-size: 20px !important; /* Force your exact base layout text size */\n        line-height: 1.5 !important;\n    }\n    .fancybox-inner h1, .fancybox-inner h2 {\n        font-size: 32px !important; \n    }\n    .fancybox-inner h3, .fancybox-inner h4 {\n        font-size: 28px !important; \n    }\n}\n', 'davidk-theme', '', 'inherit', 'closed', 'closed', '', '167-revision-v1', '', '', '2026-07-30 15:54:48', '2026-07-30 19:54:48', '', 167, 'https://davidkausek.com/?p=1680', 0, 'revision', '', 0),
(1682, 1, '2026-07-30 17:14:42', '2026-07-30 21:14:42', '<!-- wp:cover {"url":"https://davidkausek.com/wp-content/uploads/2026/05/20151005202811-221fb275-me.jpg","id":194,"isRepeated":true,"dimRatio":80,"overlayColor":"custom-dark-gray","isUserOverlayColor":true,"focalPoint":{"x":0.51,"y":0.03},"minHeight":360,"contentPosition":"top left","sizeSlug":"full","className":"subpageHeader","style":{"spacing":{"padding":{"left":"4vw","top":"8vh","bottom":"4vh","right":"4vw"}}},"layout":{"type":"constrained"}} -->\n<div class="wp-block-cover is-repeated has-custom-content-position is-position-top-left subpageHeader" style="padding-top:8vh;padding-right:4vw;padding-bottom:4vh;padding-left:4vw;min-height:360px"><div class="wp-block-cover__image-background wp-image-194 size-full is-repeated" style="background-position:51% 3%;background-image:url(https://davidkausek.com/wp-content/uploads/2026/05/20151005202811-221fb275-me.jpg)"></div><span aria-hidden="true" class="wp-block-cover__background has-custom-dark-gray-background-color has-background-dim-80 has-background-dim"></span><div class="wp-block-cover__inner-container"><!-- wp:heading {"className":"animated fadeIn slow","style":{"elements":{"link":{"color":{"text":"var:preset|color|custom-link-red"}}}},"textColor":"custom-link-red"} -->\n<h2 class="wp-block-heading animated fadeIn slow has-custom-link-red-color has-text-color has-link-color">Capture Your Story</h2>\n<!-- /wp:heading -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow","style":{"elements":{"link":{"color":{"text":"var:preset|color|white"}}},"typography":{"fontSize":"1.3em","lineHeight":"1.5"},"spacing":{"padding":{"top":"0.5em","bottom":"0em"}}},"textColor":"white"} -->\n<p class="animated fadeIn slow has-white-color has-text-color has-link-color" style="padding-top:0.5em;padding-bottom:0em;font-size:1.3em;line-height:1.5">Professional photography tailored for headshots, weddings, events, and fine‑arts. </p>\n<!-- /wp:paragraph -->\n\n<!-- wp:paragraph {"className":"animated fadeIn slow","style":{"elements":{"link":{"color":{"text":"var:preset|color|white"}}},"typography":{"fontSize":"1.3em","lineHeight":"1.5"},"spacing":{"padding":{"top":"0em","bottom":"0.5em"}}},"textColor":"white"} -->\n<p class="animated fadeIn slow has-white-color has-text-color has-link-color" style="padding-top:0em;padding-bottom:0.5em;font-size:1.3em;line-height:1.5"><em>Prints (canvas, fine‑art, photo books) available on request.</em></p>\n<!-- /wp:paragraph -->\n\n<!-- wp:spacer {"height":"0.5em","metadata":{"blockVisibility":{"viewport":{"tablet":false,"mobile":false}}}} -->\n<div style="height:0.5em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons -->\n<div class="wp-block-buttons"><!-- wp:button {"className":"animated fadeIn slow is-style-fill","style":{"border":{"width":"2px","radius":{"topLeft":"32px","topRight":"32px","bottomLeft":"32px","bottomRight":"32px"}},"spacing":{"padding":{"left":"24px","right":"24px","top":"10px","bottom":"10px"}},"typography":{"fontSize":"1.15em"}}} -->\n<div class="wp-block-button animated fadeIn slow is-style-fill"><a class="wp-block-button__link has-custom-font-size wp-element-button" href="#packages" style="border-width:2px;border-top-left-radius:32px;border-top-right-radius:32px;border-bottom-left-radius:32px;border-bottom-right-radius:32px;padding-top:10px;padding-right:24px;padding-bottom:10px;padding-left:24px;font-size:1.15em">Explore packages</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {"className":"animated fadeIn slow is-style-fill","style":{"border":{"width":"2px","radius":{"topLeft":"32px","topRight":"32px","bottomLeft":"32px","bottomRight":"32px"}},"spacing":{"padding":{"left":"24px","right":"24px","top":"10px","bottom":"10px"}},"typography":{"fontSize":"1.15em"}}} -->\n<div class="wp-block-button animated fadeIn slow is-style-fill"><a class="wp-block-button__link has-custom-font-size wp-element-button" href="#form" style="border-width:2px;border-top-left-radius:32px;border-top-right-radius:32px;border-bottom-left-radius:32px;border-bottom-right-radius:32px;padding-top:10px;padding-right:24px;padding-bottom:10px;padding-left:24px;font-size:1.15em">Get a quote</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:spacer {"height":"2em"} -->\n<div style="height:2em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:cover {"isUserOverlayColor":true,"minHeight":300,"contentPosition":"center center","sizeSlug":"large","style":{"spacing":{"margin":{"top":"-0.5em"}},"css":"padding-left: 2vw;\\npadding-right: 3vw;"},"layout":{"type":"constrained","contentSize":"1150px"},"anchor":"packages"} -->\n<div class="wp-block-cover has-custom-css" style="margin-top:-0.5em;min-height:300px" id="packages"><span aria-hidden="true" class="wp-block-cover__background has-background-dim-100 has-background-dim"></span><div class="wp-block-cover__inner-container"><!-- wp:spacer {"height":"3em","metadata":{"blockVisibility":{"viewport":{"desktop":false,"tablet":false}}}} -->\n<div style="height:3em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:heading {"level":5,"className":"animated fadeIn slow","style":{"typography":{"textAlign":"left","fontSize":"1.8em","lineHeight":"1.8","fontStyle":"normal","fontWeight":"400"}},"fontFamily":"system-font"} -->\n<h5 class="wp-block-heading has-text-align-left animated fadeIn slow has-system-font-font-family" style="font-size:1.8em;font-style:normal;font-weight:400;line-height:1.8">From polished headshots to unforgettable wedding moments, dynamic event coverage, and high‑resolution fine‑arts documentation, our photography brings your vision to life.</h5>\n<!-- /wp:heading -->\n\n<!-- wp:spacer {"height":"3em","metadata":{"blockVisibility":{"viewport":{"desktop":false,"tablet":false}}}} -->\n<div style="height:3em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer --></div></div>\n<!-- /wp:cover -->\n\n<!-- wp:group {"backgroundColor":"custom-darker-gray","layout":{"type":"constrained","contentSize":"1200px"}} -->\n<div class="wp-block-group has-custom-darker-gray-background-color has-background"><!-- wp:columns {"className":"animated fadeIn slow","style":{"spacing":{"padding":{"top":"4em","bottom":"4em","left":"0px","right":"0px"},"blockGap":{"top":"0px","left":"4em"},"margin":{"top":"0em"}}}} -->\n<div class="wp-block-columns animated fadeIn slow" style="margin-top:0em;padding-top:4em;padding-right:0px;padding-bottom:4em;padding-left:0px"><!-- wp:column {"style":{"spacing":{"padding":{"right":"1.5em","left":"1em"}}},"layout":{"type":"constrained"}} -->\n<div class="wp-block-column" style="padding-right:1.5em;padding-left:1em"><!-- wp:heading {"level":3,"className":"animated fadeIn slow"} -->\n<h3 class="wp-block-heading animated fadeIn slow">Professional Headshots</h3>\n<!-- /wp:heading -->\n\n<!-- wp:list {"style":{"typography":{"lineHeight":"1.7","fontSize":"22px"}}} -->\n<ul style="font-size:22px;line-height:1.7" class="wp-block-list"><!-- wp:list-item {"className":"animated fadeIn slow","style":{"spacing":{"padding":{"bottom":"0.5em"}}}} -->\n<li class="animated fadeIn slow" style="padding-bottom:0.5em">Services: <!-- wp:list {"style":{"typography":{"fontSize":"0.95em"}}} -->\n<ul style="font-size:0.95em" class="wp-block-list"><!-- wp:list-item -->\n<li>Corporate, LinkedIn/Social, Actor</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"className":"animated fadeIn slow","style":{"spacing":{"padding":{"bottom":"0.5em"}}}} -->\n<li class="animated fadeIn slow" style="padding-bottom:0.5em">Where: <!-- wp:list {"style":{"typography":{"fontSize":"0.95em"}}} -->\n<ul style="font-size:0.95em" class="wp-block-list"><!-- wp:list-item -->\n<li>Studio or On‑Location (NYC Metro &amp; beyond; travel billed separately where applicable)</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item {"className":"animated fadeIn slow","style":{"spacing":{"padding":{"bottom":"0.5em"}}}} -->\n<li class="animated fadeIn slow" style="padding-bottom:0.5em">Available in 3 tiers:<!-- wp:list {"style":{"typography":{"fontSize":"0.95em"}}} -->\n<ul style="font-size:0.95em" class="wp-block-list"><!-- wp:list-item -->\n<li><em>Essential</em> - 10 edited photos, natural professional finish</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Standard</em> - 15 photos, light retouching and polish</li>\n<!-- /wp:list-item -->\n\n<!-- wp:list-item -->\n<li><em>Premium</em> - 30 photos, enhanced retouching, 3-5 business days priority turnaround</li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list --></li>\n<!-- /wp:list-item --></ul>\n<!-- /wp:list -->\n\n<!-- wp:spacer {"height":"0.5em","metadata":{"blockVisibility":{"viewport":{"mobile":false}}}} -->\n<div style="height:0.5em" aria-hidden="true" class="wp-block-spacer"></div>\n<!-- /wp:spacer -->\n\n<!-- wp:buttons {"metadata":{"blockVisibility":false},"className":"animated fadeIn slow","layout":{"type":"flex","justifyContent":"center"}} -->\n<div class="wp-block-buttons animated fadeIn slow"><!-- wp:button {"className":"fancybox-inline","style":{"typography":{"fontSize":"1.2em"}}} -->\n<div class="wp-block-button fancybox-inline"><a class="wp-block-button__link has-custom-font-size wp-element-button" href="#uniqueID" style="font-size:1.2em">View rates</a></div>\n<!-- /wp:button -->\n\n<!-- wp:button {"style":{"typography":{"fontSize":"1.2em"}}} -->\n<div class="wp-block-button"><a class="wp-block-button__link has-custom-font-size wp-element-button" href="#form" style="font-size:1.2em">Book your headshot</a></div>\n<!-- /wp:button --></div>\n<!-- /wp:buttons -->\n\n<!-- wp:html -->\n<div class="wp-block-buttons is-content-justification-center is-layout-flex wp-container-core-buttons-is-layout-35f06ea7 wp-block-buttons-is-layout-flex animated fadeIn slow">\n  \n